programs.sol:
"""Approximate two strong negative responses: assistant labels and Indic clusters.

The exact assistant token gets a strong negative pulse, especially in chat
headers; whitespace and case variants get a smaller one. In Indic text, joining consonants with a virama is strongly
negative. Gurmukhi also has negative responses to adjoining consonants and
combining marks. These are coarse orthographic rules, not a model of prose.
"""
import unicodedata

READS = ()
VIRAMAS = frozenset('्্੍્୍்్್്්္')
GURMUKHI_LIQUIDS = frozenset('ਰਲਲ਼')


def cluster_response(text):
    last = text[-1] if text else ''
    previous = text[-2] if len(text) > 1 else ''
    if previous in VIRAMAS:
        if last == '\ufffd':
            return -1.7 if previous == '்' else -2.3
        return -2.1
    if last in VIRAMAS:
        return -0.48
    if '\u0a00' <= last <= '\u0a7f':
        category = unicodedata.category(last)
        if category.startswith('M'):
            return 0.05 if last == 'ੰ' else -0.50
        if category == 'Lo':
            if previous in GURMUKHI_LIQUIDS:
                return -1.42
            if (previous == 'ੰ' or
                ('\u0a00' <= previous <= '\u0a7f' and
                 unicodedata.category(previous) == 'Lo')):
                return -0.76
            return -0.14
    if last == '\ufffd' and '\u0a00' <= previous <= '\u0a7f':
        return -0.92 if previous in GURMUKHI_LIQUIDS else -0.19
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
        # Character offset prevents looking across a packed-document boundary.
        start = prefix.position
        offset = len(prefix.text_prefixes[start - 1]) if start else 0
    else:
        _, previous, tail, offset = carry

    if '\ufffd' in token or '\ufffd' in tail:
        # Only byte-fragment tokens need decoding together with the prefix.
        tail = prefix.text_prefixes[-1][offset:][-4:]
    else:
        tail = (tail + token)[-4:]

    if token == 'assistant':
        value = -0.809 if previous == '<|im_start|>' else -0.59
    elif token.strip().lower() == 'assistant':
        value = -0.20
    elif not token.isascii():
        value = cluster_response(tail)
    else:
        value = 0.0
    return (doc, token, tail, offset), value

"""Approximate positive Greek-script activity and negative chat boundaries.

A 16-token script history gates Greek responses, suppressing most isolated
math symbols. Vowels, accents, case and word boundaries set their strength.
Turn-separating newlines and role names are strongly negative; other markup
has small fixed responses. Short Latin fragments or digits immediately after
several non-Latin scripts are negative. Unmatched cases return zero.
All history resets when the document changes.
"""
from functools import lru_cache
import unicodedata as ud

READS = ()
# Responses for unaccented and accented Greek vowels, respectively.
GREEK_VOWELS = {
    'α': (1.29, .65),  # alpha
    'ε': (1.09, .75),  # epsilon
    'η': (.78, .30),   # eta
    'ι': (1.30, 1.0),  # iota
    'ο': (.37, .38),   # omicron
    'υ': (1.06, .44),  # upsilon
    'ω': (.35, -.02),  # omega
}
MARKERS = {
    '<|im_end|>': .095,
    '<|im_start|>': .03,
    '<think>': -.16,
    '</think>': .094,
    '<tool_response>': -.055,
}


@lru_cache(maxsize=8192)
def scripts(s):
    names = [ud.name(c, '') for c in s if c.isalpha()]
    greek = any('GREEK' in n for n in names)
    foreign = any('CYRILLIC' in n or 'ARABIC' in n for n in names)
    latin = bool(names) and all('LATIN' in n for n in names)
    # Strength of a switch from this script into Latin letters or digits.
    strength = 0.
    for script, weight in (('GREEK', .5), ('CYRILLIC', 1.1),
                           ('ARABIC', .55), ('CJK', .18),
                           ('HIRAGANA', .33), ('KATAKANA', .65),
                           ('HANGUL', .48), ('THAI', .8)):
        if any(script in n for n in names):
            strength = max(strength, weight)
    return greek, foreign, latin, len(names), strength


def greek_response(s, previous):
    letters = ''.join(c for c in s if c.isalpha())
    decomposed = ud.normalize('NFD', letters.lower())
    bases = ''.join(c for c in decomposed if not ud.combining(c))
    accented = len(bases) < len(decomposed)
    if not bases:
        return 0.0
    if accented:
        value = GREEK_VOWELS.get(bases[0], (1.05, .6))[1]
        if '\u0342' in decomposed:  # Greek circumflex
            value -= .85
    elif bases == 'ς':
        value = .8
    else:
        value = sum(GREEK_VOWELS.get(c, (1.05, .6))[0] for c in bases) / len(bases)
        if len(bases) > 1:
            value *= .65
        elif not s.startswith(' '):
            last = ud.normalize('NFD', previous[-1:])
            adjustment = (.45 if len(last) > 1 else
                          .40 if last == 'ε' else .25 if last == 'ο' else 0.)
            value -= adjustment * (.5 if bases in 'οω' else 1.)
    if letters[0].isupper():
        value *= .65
    if s.startswith(' '):
        value -= .15
    return value


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before, history = '', '', ()
    else:
        _, previous, before, history = carry
    if '\ufffd' in s:
        # A token decoded alone may hide a completed multi-byte character.
        completed = prefix.text_prefixes[-1][-1:]
        if completed.isalpha():
            s = (' ' if s.startswith(' ') else '') + completed
    greek, foreign, latin, length, _ = scripts(s)
    prev_greek, _, _, _, switch_strength = scripts(previous)
    # Cyrillic/Arabic context strengthens negative chat-boundary responses.
    foreign_share = sum(h[1] for h in history) / max(1, len(history))
    greek_context = prev_greek or sum(h[0] for h in history) > 4
    value = MARKERS.get(s, 0.)
    if s == '\n' and previous == '<|im_end|>':
        value = -1.57 - .59 * foreign_share
        if before == '</tool_call>':
            value -= .48
        elif before == '</tool_response>':
            value -= .33
        if scripts(before)[1]:
            value -= .45
        if before.endswith('。'):
            value += .19
    elif previous == '<|im_start|>':
        if s == 'user':
            value = -1.913 if before != '\n' else -2.46 - foreign_share
        elif s == 'assistant':
            value = -1.0 - .50 * foreign_share
        elif s == 'system':
            value = -1.25
    elif s == '\n' and previous in ('<tool_response>', '<tool_call>'):
        value = -.39
    elif s == '\n\n' and previous == '</think>':
        value = -.30
    elif greek and greek_context:
        value = greek_response(s, previous)
    elif '\ufffd' in s and greek_context:
        value = .45
    elif switch_strength and latin and length <= 4:
        value = -switch_strength / length ** .7
    elif switch_strength and s.strip().isdigit():
        value = -.8 * switch_strength
    elif s == 'O' and previous == '\n' and before == '<tool_response>':
        value = -.75
    history = (history + ((greek, foreign),))[-16:]
    return (doc, s, previous, history), float(value)

programs.haiku:
"""Layer-0 MLP neuron 5573 (down_proj), a 'chat-role and Greek-word' feature.

It is most negative on the chat-template markers: the role name 'user' right after
'<|im_start|>' (about -2.4, a little less negative in the first turn), and on the newline
that follows '<|im_end|>' (about -1.8). It is moderately negative on 'assistant' after
'<|im_start|>' (-1.0) and on the newline after '<tool_call>' / '<tool_response>' (about -0.4).
It is positive inside Greek words: a Greek letter right after another Greek letter; plain
letters give about +1.0, accented letters and omicron/omega about +0.4.
Everything else is near zero.
"""

import unicodedata

READS = ()


def _greek_letters(s):
    s = s.strip()
    return len(s) > 0 and all(ch.isalpha() and "GREEK" in unicodedata.name(ch, "") for ch in s)


def _plain_greek(s):
    s = s.strip()
    return s not in ("ο", "ω", "ό", "ώ", "ή", "ύ", "ί", "έ", "ά", "ου")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    cur = toks[t]
    prev = toks[t - 1] if t > 0 else ""
    if prev == "<|im_start|>":
        if cur == "user":
            return carry, -2.4
        if cur == "assistant":
            return carry, -1.0
    if prev == "<|im_end|>" and cur == "\n":
        return carry, -1.8
    if prev in ("<tool_call>", "<tool_response>") and cur == "\n":
        return carry, -0.4
    if _greek_letters(cur) and _greek_letters(prev):
        return carry, 1.0 if _plain_greek(cur) else 0.4
    return carry, 0.0

programs.sol:
"""Predict a negative response to compact colon separators.

Quotes, brackets, or a space attached before the colon strengthen the response;
a following line break generally weakens it. Numbers, single-letter words, and
source filenames
before the colon strengthen it further. Field labels and prose introductions
are weaker. URL colons and double-colon namespace separators are nearly silent.
Non-colon tokens return zero. A short text tail and token count are carried
within each document, and reset at document boundaries.
"""
import re

READS = ()
FIELD_LABELS = frozenset('''name type title question answer author source category
location date time description note warning error status input output result
message code file filename directory id email address phone occupation country
citizenship birth team views posts joined topic replies forum'''.split())
INTRODUCERS = frozenset('''following follows include includes including example
examples is are as that this to wrote steps questions below except else try'''.split())
FUNCTION_WORDS = frozenset('''a an the of in on at with from and or but for by be
been being will can would could should may might it its they their you your we
our i'''.split())
SOURCE_SUFFIXES = (
    '.py', '.java', '.php', '.go', '.rs', '.cpp', '.c', '.h', '.ts', '.js',
)
WORD = re.compile(r'[\w.\-]+$')


def colon_response(token, previous, recent, position):
    if ':' not in token and '：' not in token:
        return 0.0
    if '://' in token:
        return 0.0
    if '::' in token:
        return 0.08
    before, _, after = token.partition(':' if ':' in token else '：')
    newline = '\n' in after or '\r' in after
    if after.startswith('='):
        return -0.37
    if '：' in token:
        value = 0.02 if newline else -0.35
    elif before.isspace():
        value = -0.65 if newline else -1.22
    elif '"' in before or "'" in before:
        value = -0.78 if newline else -1.49
    elif any(c in before for c in ')]}'):
        value = -0.44 if newline else -1.20
        if not newline and before.count(')') > 1:
            value -= 0.53
    elif before and set(before) == {'*'}:
        value = -0.82
    elif before:
        value = -1.23
    elif newline:
        value = -0.095
    elif after.startswith('"'):
        value = -0.24
    else:
        value = -0.55 if after else -0.51

    if not before and after.count('\n') > 1 and '：' not in token:
        value += 0.06

    # The word just before this token supplies the separator's context.
    match = WORD.search(recent.rstrip())
    word = match.group(0) if match else ''
    if not any(c.isalnum() for c in word):
        word = ''
    lower = word.lower()
    if word and word[-1].isdigit():
        value -= 0.48 if newline else 0.69
    if len(word) == 1 and word.isalpha():
        value -= 0.39 if newline else 0.68
    if len(word) > 1 and word.isupper():
        value -= 0.08 if newline else 0.37
    if (0 < len(word) <= 3 and not word[-1].isdigit()
            and not word.isupper() and not (len(word) == 1 and word.isalpha())
            and lower not in FIELD_LABELS | INTRODUCERS | FUNCTION_WORDS):
        value -= 0.16
    if lower in FIELD_LABELS:
        value += 0.21 if newline else 0.39
        # A standalone metadata label at a line/document opening is weaker.
        if token == ':' and recent.rsplit('\n', 1)[-1].strip() == word:
            value += 0.43
        if token == ':' and position <= 4:
            value += 0.70
    if lower in INTRODUCERS:
        value += 0.28 if newline else 0.39
    if lower in FUNCTION_WORDS:
        value += 0.03 if newline else 0.20
    if previous and not previous[0].isspace():
        value -= 0.16 if newline else 0.15
    if not word and recent:
        value -= 0.60 if newline else 0.62
    if lower.endswith(SOURCE_SUFFIXES):
        value -= 0.31 if newline else 0.56
        if lower.endswith(('.java', '.php')):
            value -= 0.56 if newline else 0.93
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    doc, previous, recent, position = carry
    token = prefix.token_strings[-1]
    value = colon_response(token, previous, recent, position)
    return (doc, token, (recent + token)[-128:], position + 1), float(value)

programs.luna:
"""A small punctuation detector for a component that usually reacts to colons.

The harvest's large responses cluster on colon marks in prose, code, logs, and
structured text. It predicts a negative pulse there, smaller for fullwidth or
line-ending colons; elsewhere it predicts the component's small average offset.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = -0.00957
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""

    if "：" in token:
        value = -0.30
    elif ":" in token:
        if token.endswith((":\n", ":\n\n")):
            value = -0.45
        elif token[:1] in ')]}"\'![' or token.startswith('\\"'):
            value = -1.95
        elif previous.rstrip().endswith(tuple("0123456789")):
            value = -1.55
        else:
            value = -1.15

    return carry, value

programs.sol:
"""Approximate a quoted-string opener detector, plus a lexical negative cue.

Quotes preceded by whitespace, braces, brackets or escaping fire strongly;
quotes followed by punctuation generally do not. The previous two tokens
refine prose versus printing calls and JSON name fields. The words
'relationship', 'relationships' and Chinese '关系' give negative responses.
Other words are mostly left at zero; fine token-specific variation is omitted.
"""

READS = ()
PRINT_CALLS = {'print', 'printf', 'println', 'log', 'info', 'writeline'}
STRING_PREFIXES = {'f', 'r', 'b', 'u', 'fr', 'rf', 'br', 'rb'}
ASCII_QUOTES = '\"\''


def recent(prefix, distance):
    """Read a nearby token only if it belongs to the current document."""
    if len(prefix.token_ids) <= distance:
        return ''
    if prefix.document_ids[-1 - distance] != prefix.document_ids[-1]:
        return ''
    return prefix.token_strings[-1 - distance]


def strength(token, prev, older):
    word = token.strip().lower()
    if word in {'relationship', 'relationships', '关系'}:
        if word == '关系':
            return -1.4
        return -3.0 if word == 'relationship' else -2.65
    if token in {'`', '``', ' `'}:
        return 0.15 if token.startswith(' ') else -0.11
    if not token:
        return 0.0
    spaced = token.startswith(' ')
    if token[-1] in '「『':
        return 0.32
    if token[-1] in '“‘«„':
        if spaced:
            return 0.91
        if len(token) > 1:
            return 0.25 if token[-2] == '：' else 0.75
        return 0.70 if prev[-1:].isalnum() else 0.36
    if token[-1] in '”’»':
        return (0.32 if token[-1] == '»' else 0.65) if spaced else 0.04
    count = sum(token.count(c) for c in ASCII_QUOTES)
    if not count:
        return 0.0
    if token[-1] not in ASCII_QUOTES:
        if token.lstrip().startswith('"""'):
            return 0.35
        return 0.20 if '\\"' in token else -0.03

    before, quote = token[:-1], token[-1]
    if '\\' in before:
        return 0.4 if quote == "'" else (1.5 if spaced else 1.18)
    if '`' in before or any(q in before for q in ASCII_QUOTES if q != quote):
        return 2.5 if spaced else 1.6
    if count >= 3:
        return 0.45
    if count == 2:
        if before.strip() == quote:
            return 1.2 if quote == '"' else 0.7
        if ':' in before:
            return 1.8
        return 1.5 if any(c in before for c in ',[{') else 0.6
    if '{' in before:
        return 1.6
    if '[' in before:
        return 1.6 if spaced else 1.35
    if '(' in before:
        if '!' in before or '=' in before:
            return 1.4
        if prev.strip().lstrip('.').lower() in PRINT_CALLS:
            return 0.22
        return 1.15 if spaced else 0.6
    if '=' in before:
        return 0.5 if quote == '"' else 0.85
    if '<' in before:
        return 1.3 if quote == '"' else 1.85
    if ':' in before:
        return 0.85
    if ',' in before:
        if spaced or ']' in before:
            return 1.4
        return 0.2 if quote == '"' else 0.64
    if before.isspace():
        if prev == '\":' and older.strip().lower() == 'name':
            return 0.02
        if prev[-1:].isalnum():
            return 0.98
        return 0.88 if quote == "'" else 0.72
    if not before:
        if not prev or '\n' in prev:
            return 0.6
        if prev.isspace():
            return 1.0
        if prev.lstrip(' (').lower() in STRING_PREFIXES:
            return 0.8
        if prev == 'n' and older.endswith('\\'):
            return 0.65
    return 0.15


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    return None, strength(token, recent(prefix, 1), recent(prefix, 2))

programs.haiku:
"""Opening-quote detector (v4): fires on the quote mark that opens a quotation or string literal."""
from collections.abc import Mapping

READS = ()

# quote marks that open a string or quotation (closing ” ’ » are left out)
OPENERS = set("\"'“‘«„")
# how strongly an opening quote fires, by the character just before it
BEFORE = {"{": 1.6, ":": 1.5, "[": 1.4, "\\": 1.2, " ": 0.85, "(": 0.55, "=": 0.5, ",": 0.45}
# the word "relationship" pushes strongly negative; related words weakly so
RELATIONSHIP = {"relationship", "relationships"}
RELATED = {"relation", "relations", "friendship", "partnership"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    if word in RELATIONSHIP:
        return carry, -2.8
    if word in RELATED:
        return carry, -0.3
    if not tok or tok[-1] not in OPENERS:
        return carry, 0.0
    if len(tok) > 1:
        return carry, BEFORE.get(tok[-2], 0.5)
    # a bare quote: weak after a word, as the previous token shows
    prev = prefix.token_strings[-2][-1:] if len(prefix) > 1 else " "
    if prev.isalnum():
        return carry, 0.2
    return carry, BEFORE.get(prev, 0.5)

programs.sol:
"""Approximate a lexical response to encompassing wholes and organized collections.

Selected nouns receive negative values, often repeated on the following 'of'.
Modifiers distinguish biological systems and physical environments; fragments
are joined to recognize biological '-ome' words and other split collection nouns.
Smaller rules cover inclusion/choice words, suffixes, and conversation formatting.
This captures a sparse lexical pattern, not the many unrelated small activations.
"""
import re
READS = ()

STRONG_WHOLES = set('landscape workforce curriculum diet diets'.split())
INVENTORIES = set('portfolio fleet arsenal'.split())
DOMAINS = set('universe cosmos repertoire itinerary genome ecosystem landscapes'.split())
CONTENTS = set('population budget budgets atlas palette timeline appetite vocabulary '
               'wardrobe lifecycle playbook encyclopedia toolkit toolbox workload'.split())
ORGANIZED_WHOLES = set('lineup roster army electorate hierarchy fauna cortex skeleton '
                      'canopy infrastructure journey lifestyle lifespan soundtrack '
                      'schedule routine agenda workflow catalogue worldview'.split())
OTHER_WHOLES = set('environment economy climate spectrum menu framework '
                  'atmosphere architecture dataset corpus cohort suite kingdom '
                  'neighborhood neighbourhood forest inbox pipeline mixture'.split())
BIOLOGICAL_SYSTEMS = set('digestive nervous cardiovascular respiratory circulatory '
                         'reproductive endocrine'.split())
OMES = set('biome proteome transcriptome metabolome metatranscriptome genome'.split())


# Standard conversation delimiters and roles, plus a fullwidth comma.
FORMATTING = {
    '<|im_end|>': -0.057,
    '</think>': -0.164,
    '</tool_call>': 0.063,
    '<|endoftext|>': 0.019,
    'assistant': -0.033,
    '，': -0.042,
}
INCLUSION_WORDS = {'such', 'those', 'including', 'among', 'throughout'}
CHOICE_WORDS = {'only', 'either', 'neither', 'any', 'same', 'enough'}
INFLECTION_ENDINGS = {'ed', 'ers', 'ing'}


def noun_value(word):
    for words, value in ((STRONG_WHOLES, -0.82), (INVENTORIES, -0.65),
                         (DOMAINS, -0.58), (CONTENTS, -0.42),
                         (ORGANIZED_WHOLES, -0.32), (OTHER_WHOLES, -0.20)):
        if word in words:
            return value
    if word in {'genomes', 'portfolios', 'fleets'}:
        return -0.44
    if word in {'populations', 'ecosystems', 'environments', 'alphabet'}:
        return -0.22
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    match = re.search(r'[a-z]+$', tail + raw.lower())
    completed = match.group() if match else ''
    value = noun_value(word)
    if word == 'library':
        value = -0.19 if raw.strip().istitle() else -0.03
    elif word == 'world':
        value = -0.06
        if previous in {'digital', 'islamic', 'arab', 'corporate', 'natural',
                        'developing', 'developed'}:
            value = -0.34
    elif word == 'environment' and previous in {'built', 'physical'}:
        value = -0.61
    elif word == 'environment' and previous in {'urban', 'indoor', 'living',
                                               'work', 'working', 'corporate'}:
        value = -0.39
    elif word == 'schedule' and previous in {'daily', 'your', 'my', 'life'}:
        value = -0.57
    elif word == 'inbox' and previous in {'your', 'my', 'our'}:
        value = -0.75
    elif word == 'alphabet' and previous in {'latin', 'greek', 'cyrillic'}:
        value = -0.50
    elif word == 'immune':
        value = -0.23
    elif word == 'system':
        value = -0.04
        if previous == 'immune':
            value = -0.60
        elif previous == 'solar':
            value = -0.50
        elif previous in BIOLOGICAL_SYSTEMS:
            value = -0.36
    elif word == 'of' and noun_value(previous) < -0.1:
        value = 0.80 * noun_value(previous)
    elif word == 'of' and previous == 'world':
        value = -0.23
    elif word in {'ome', 'omes'}:
        root = completed.removesuffix('s')
        if root == 'microbiome':
            value = -1.10 if word == 'ome' else -0.70
        elif root in OMES:
            value = -0.48
    elif len(word) >= 3 and completed != word and noun_value(completed) < -0.1:
        value = 0.70 * noun_value(completed)

    # Capitalized nouns usually have a somewhat smaller response.
    if value < -0.1 and word not in {'of', 'system', 'ome', 'omes'}:
        if raw.strip()[:1].isupper():
            value *= 0.82
    # Selection/inclusion markers have small responses of the opposite sign.
    if word in INCLUSION_WORDS:
        value = 0.055
    elif word in CHOICE_WORDS:
        value = -0.04
    elif raw in INFLECTION_ENDINGS:
        value = -0.04
    value = FORMATTING.get(raw, value)
    if raw == 'user' and previous == 'im':
        value = 0.056
    if raw.strip():
        previous = 'im' if raw == '<|im_start|>' else completed or word
    return (doc, previous, completed[-40:]), value

programs.luna:
"""Use a weak lexical cue for words naming broad systems, settings, or collections.

The vocabulary is a readable sketch of a recurring cluster in the harvested examples;
tracking word pieces lets the cue recognize a word split across tokens.
"""
READS = ()

WHOLE_SYSTEM_WORDS = {
    "alphabet", "budget", "budgets", "curriculum", "diet", "ecosystem",
    "environment", "genome", "inbox", "itinerary", "landscape",
    "population", "portfolio", "repertoire", "system", "universe",
    "workforce",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, previous = "", ""
    else:
        _, word, previous = carry

    matched = False
    for char in prefix.token_strings[-1].casefold():
        if char.isalpha():
            word += char
            matched = matched or word in WHOLE_SYSTEM_WORDS
        else:
            if word:
                previous = word
            word = ""

    value = -0.17 if matched else 0.0
    if word == "of" and previous == "universe":
        value = -0.17
    return (doc, word, previous), value

