programs.sol:
"""Predict a mostly negative response to the token immediately after 'of'.

Pronoun classes and fixed phrases set its strength: 'of which/whom',
'of course', and 'of them' are strongest. Quantifiers before 'of' sometimes
increase it. Other prepositions give smaller pronoun responses. The same
spelling also triggers within words and identifiers. Unknown content words
are approximated near zero, rather than memorized individually.
"""

READS = ()

# Grammatical classes of complements, with strengths learned on training text.
COMPLEMENTS = (
    (4.9, {'which', 'whom'}),
    (3.3, {'them'}),
    (2.15, {'it', 'us', 'you'}),
    (1.48, {'me', 'him'}),
    (2.8, {'mine', 'yours', 'ours', 'theirs'}),
    (1.8, {'myself', 'yourself', 'himself', 'herself', 'ourselves',
           'yourselves', 'themselves'}),
    (3.0, {'itself'}),
    (1.02, {'this', 'these'}),
    (0.54, {'that', 'those'}),
    (0.75, {'each', 'what'}),
    (1.3, {'whether'}),
    (0.47, {'how'}),
    (0.17, {'any'}),
    (1.20, {'all'}),
    (0.43, {'both', 'either', 'neither'}),
    (0.49, {'its'}),
    (0.33, {'his', 'her', 'their'}),
    (0.24, {'my', 'your', 'our'}),
)
STRENGTH = {word: value for value, words in COMPLEMENTS for word in words}

# Fixed 'of ...' expressions rather than arbitrary content-word predictions.
OF_IDIOMS = {'course': 4.18, 'late': 2.5, 'interest': 2.03,
             'sorts': 2.9, 'nowhere': 1.8}
# Nouns in expressions specifying a kind, shape, or measurement.
OF_ATTRIBUTES = {'type': 1.6, 'form': 1.3, 'size': 1.2, 'shape': 1.1,
                 'length': 0.9, 'age': 0.85, 'kind': 0.85, 'sort': 0.85}
PREPOSITIONS = {
    'for': 0.23, 'from': 0.18, 'to': 0.15, 'about': 0.19,
    'among': 0.44, 'amongst': 0.35, 'between': 0.22,
    'on': 0.08, 'in': 0.025,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    bare = token.strip(' _.-')
    word = bare.lower()
    before_word = before.strip().lower()
    prep = previous.strip(' _.-').lower()
    value = 0.0
    if prep == 'of':
        strength = STRENGTH.get(word, OF_IDIOMS.get(word,
                   OF_ATTRIBUTES.get(word, 0.0)))
        # Capital-letter acronyms (IT, US) are not personal pronouns.
        if bare.isupper() and word in STRENGTH:
            strength = 0.0
        if word == 'all' and before_word == 'first':
            strength = 3.4
        elif word in {'this', 'these', 'that', 'those'}:
            if before_word in {'all', 'each', 'both'}:
                strength += 0.5
            elif before_word in {'most', 'some', 'none'}:
                strength += 0.2
        if token.startswith('_') and word in OF_IDIOMS:
            strength *= 1.35
        if not strength and token and not token[0].isspace() and bare.isalpha():
            # A continuation inside a word or an identifier containing 'of'.
            strength = 0.7
        # Java Optional.ofNullable constructs an optional value.
        if token == 'Nullable':
            strength = 3.8
        if token.isspace():
            strength = 0.51
        elif token.strip() in {',', ':', '-', ')'}:
            strength = 0.5
        elif word in {'$', '£', '€', '¥'}:
            strength = 0.48
        elif word in {'a', 'an'}:
            strength = -0.11 if word == 'a' else -0.19
        elif word == 'the':
            strength = -0.05
            if before_word in {'all', 'many', 'each', 'both'}:
                strength += 0.3
            elif before_word in {'most', 'some', 'any', 'two'}:
                strength += 0.15
        elif not strength and token.startswith(' '):
            strength = -0.18 if word.endswith('ing') else -0.05
        value = -strength
        if previous.strip() in {'Of', 'OF'}:
            value *= 0.87
    elif prep in PREPOSITIONS:
        value = -PREPOSITIONS[prep] * STRENGTH.get(word, 0.0)
    elif word == 'course':
        value = 1.45 if prep == 'this' else 0.95 if prep == 'the' else 0.5
    elif word in {'kind', 'sort'} and prep in {'some', 'any'}:
        value = -1.0
    return (doc, token, previous), float(value)

