"""layers.0.mlp.down_proj:5580, explained.

This component is almost silent everywhere. Its rare large responses come on the word
right after "of" (or "Of"): it goes strongly negative when that word is a pronoun or a
quantifier/demonstrative, the way "of which", "of whom", "of them", "of us", "of it",
"of course", and milder for "of this", "of these", "of all", "of each", "of those",
"of its/his/their". Smaller negatives follow for "to/for/from/among + which/whom/them".
Everywhere else (content nouns, "the", "a") it stays at 0.
"""

READS = ()

# Pronouns that refer back or complete "of": strongest response.
STRONG = {"which", "whom", "course", "them", "us", "it", "you", "yours"}
# Demonstratives, quantifiers and possessives after "of": milder response.
DEMONSTRATIVE_OR_QUANTIFIER = {
    "this", "these", "those", "all", "each", "both", "such", "that", "what", "any", "either",
    "its", "his", "their", "our", "your", "my", "her",
}
# Prepositions other than "of" that take a relative/object pronoun more weakly.
OTHER_PREPOSITIONS = {"to", "for", "from", "among", "between", "about", "toward", "against", "amongst"}
PRONOUN_OBJECTS = {"which", "whom", "them", "us"}


def step(carry, prefix, upstream):
    value = 0.0
    if len(prefix.token_strings) >= 2 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        before = prefix.token_strings[-2].strip().lower()
        word = prefix.token_strings[-1].strip().lower()
        if before == "of":
            if word in STRONG:
                value = -3.0
            elif word in DEMONSTRATIVE_OR_QUANTIFIER:
                value = -0.8
        elif before in OTHER_PREPOSITIONS and word in PRONOUN_OBJECTS:
            value = -0.8
    return carry, value

programs.luna:
"""Predict a negative response to selected preposition complements.

The sampled strong responses often follow “of”, especially short pronouns or
demonstratives, or a standalone whitespace token.  Relative “which” also
appears after “to” and “from”.  This compact rule captures those patterns and
ignores the many other words after common prepositions.
"""

READS = ()

PRONOUNS_AND_DEMONSTRATIVES = {"this", "these", "that", "it", "each"}


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous = prefix.token_strings[-2].strip().casefold()
    current = prefix.token_strings[-1].strip().casefold()
    if previous == "of" and (
        current in PRONOUNS_AND_DEMONSTRATIVES
        or not current
        or current in {",", ":"}
    ):
        return None, -0.65
    if previous in {"to", "from"} and current == "which":
        return None, -0.65
    return None, 0.0

