            value -= 0.18
    elif word in GRANDEUR:
        value = -0.21
    elif word in VISUAL_APPEAL:
        value = -0.12
    elif word == 'scenery':
        value = -0.32
        if previous in {'natural', 'beautiful', 'breathtaking'}:
            value -= 0.30
    elif word in {'landscape', 'landscapes'}:
        value = -0.15 if word == 'landscape' else -0.23
        if previous in {'natural', 'beautiful'}:
            value -= 0.13
    elif word == 'cottage':
        value = -0.49 if spelling.islower() else -0.33
    elif word == 'attractions':
        value = -0.30
    elif word in TOURISM:
        value = -0.13
    elif word == 'remarkable':
        value = -0.25
    elif word in PHOTOGRAPHY:
        value = 0.13
    elif word in {'photo', 'photos'}:
        value = 0.04
    elif word == 'digital':
        value = 0.10
    elif word == 'digitally':
        value = 0.25
    elif word == 'buildings':
