    elif word == 'building':
        value = -0.08
    elif spelling in CHINESE_BEAUTY:
        value = -0.30
    elif spelling in CHINESE_SCENERY:
        value = -0.31
        if previous == '自然':
            value -= 0.18
    elif spelling in CHINESE_GRANDEUR:
