programs.sol:
"""Recognize quantitative change and comparative/subjective assessments.

Both increases and decreases produce positive values: this is a change cue,
not a signed estimate of quantity. Inflections have different strengths.
The cue persists onto 'the' after a change verb, 'of' after a change noun,
and 'to' after 'likely', with weaker responses on possessives and 'in'.
Strong degree adverbs amplify change/comparison cues. Subjective reports and
a few Chinese change terms are also recognized. Unmatched tokens receive zero,
omitting the component's diffuse weaker lexical activity. Only the preceding
word and unfinished word-piece are remembered; both reset between documents.
"""
import re

READS = ()

# Strengths for base, third-person, past, and present-participle forms.
VERBS = {
    'increase': (1.07, 0.98, 0.89, 0.98),
    'decrease': (0.90, 0.91, 0.83, 0.78),
    'reduce': (0.80, 0.73, 0.63, 0.80),
    'improve': (0.88, 0.92, 0.68, 0.87),
    'enhance': (0.39, 0.39, 0.22, 0.41),
}
INFLECTIONS = {}
for root, strengths in VERBS.items():
    forms = (root, root + 's', root + 'd', root[:-1] + 'ing')
    for form, strength in zip(forms, strengths):
        INFLECTIONS[form] = (root, strength)

CHANGE_NOUNS = {
    'reduction': 0.58, 'reductions': 0.61,
    'improvement': 0.40, 'improvements': 0.51,
}
COMPARISONS = {
    'higher': 0.42, 'lower': 0.35, 'fewer': 0.54,
    'older': 0.37, 'younger': 0.23, 'shorter': 0.33,
    'longer': 0.08, 'smaller': 0.15, 'larger': 0.12,
    'greater': 0.11, 'less': 0.12, 'more': -0.05,
}
ASSESSMENTS = {
    'likely': 0.24, 'satisfaction': 0.61, 'attitudes': 0.59,
    'perceived': 0.45, 'perception': 0.22, 'perceptions': 0.75,
}
CHINESE_CHANGE = {
    '提高': 1.02, '提升': 0.72, '增加': 0.53,
    '减少': 0.63, '降低': 0.52,
}
THE_AFTER_VERB = {
    'increase': 0.69, 'decrease': 0.55, 'reduce': 0.65,
    'improve': 0.50, 'enhance': 0.31,
}
INTENSIFIERS = {
    'significantly', 'greatly', 'dramatically', 'markedly', 'drastically',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, family, tail = '', '', ''
    else:
        _, previous, family, tail = carry
    raw = prefix.token_strings[-1]
    text = raw.lower()
    joined = tail + text if text and text[0].isalpha() else text
    match = re.search(r'[a-z]+$', joined)
    word = match.group() if match else text.strip()
    root, value = INFLECTIONS.get(word, ('', 0.0))
    if not root:
        value = CHANGE_NOUNS.get(word, COMPARISONS.get(
            word, ASSESSMENTS.get(word, 0.0)))
    for cue, strength in CHINESE_CHANGE.items():
        if cue in raw:
            value = strength
            break
    if (root or word in COMPARISONS) and previous in INTENSIFIERS:
        value += 0.28
    if word in {'increase', 'decrease'} and previous in {'a', 'an', 'the'}:
        value -= 0.12
    if word == 'likely' and previous in {'more', 'less'}:
        value = 0.53
    if word == 'to' and previous == 'likely':
        value = 0.53
    if text.strip() == '-reported' and previous in {'self', 'parent'}:
        value = 0.95
    if text.strip() == '-being' and previous == 'well':
        value = 0.61

    if word == 'the':
        value = THE_AFTER_VERB.get(family, value)
    elif word in {'their', 'its', 'your', 'our', 'my', 'his', 'her'}:
        if family in VERBS:
            value = 0.39 if word in {'their', 'its'} else 0.23
            if family == 'enhance':
                value *= 0.5
    elif word == 'of':
        if previous in {'increase', 'decrease', 'reduction', 'reductions'}:
            value = 0.49
        elif previous in {'improvement', 'improvements'}:
            value = 0.24
    elif word == 'in':
        if previous in {'increase', 'increases', 'increasing'}:
            value = 0.15
        elif previous in {'reduction', 'reductions'}:
            value = 0.25

    tail = word[-32:] if match else ''
    return (doc, word, root, tail), float(value)

