"""Draft 3: graded list of change words, plus the determiner right after one."""
READS = ()

# Verbs of quantity change (increase / decrease / improve, and Chinese equivalents).
STRONG = {
    "increase", "increases", "increased", "increasing", "increase's",
    "decrease", "decreases", "decreased", "decreasing",
    "improve", "improves", "improved", "improving",
    "提高", "提升", "增加", "减少", "降低",
}
