    "higher", "lower", "fewer", "shorter", "lowers", "lowered", "lowering",
    "improvement", "improvements", "enhance", "enhances", "enhancing", "enhanced",
    "minimize", "maximize", "diminish", "boost", "boosted", "elevated",
}
# Small positive for other comparison/likelihood words.
SMALL = {"less", "greater", "larger", "smaller", "high", "likely", "increasingly"}
# Words right after a change verb that take its object: "reduce [the]", "increase [of]".
OBJECT_WORDS = {"the": 0.5, "of": 0.4, "their": 0.4, "its": 0.35, "your": 0.2}

LEVEL = {w: 0.95 for w in STRONG}
LEVEL.update({w: 0.7 for w in MEDIUM})
LEVEL.update({w: 0.4 for w in WEAK})
LEVEL.update({w: 0.15 for w in SMALL})
