    return None, 0.0

"""Fixed English phrases. The component reacts to the word that completes (or opens) a
set phrase of manner, degree, time, reason or measure:

* After a determiner or quantifier ("in any case", "for many reasons", "at some point",
  "in some ways", "at the same time") the noun is clearly negative.
* After "at" the word "all" ("at all") and after "per" a time unit ("per second") are
  negative, as is "end" in "in the end".
* After "in", a word that closes an adverb ("in general", "in particular", "in turn",
  "in fact") is negative, while a word that opens a phrase running on to "of", "to" or
  "with" ("in order to", "in case of", "in terms of", "in view of", "in accordance
  with", "in line with") is positive.

Everything else is about zero. The values are rough, chosen from the mean activations.
"""

READS = ()

ADVERB_NOUNS = {
    "case", "cases", "point", "time", "way", "ways", "level", "moment", "occasion",
    "purpose", "purposes", "reason", "reasons", "sense", "extent", "manner", "degree",
    "side", "direction", "basis", "default", "rate", "respect", "fashion", "perspective",
    "contexts", "sake", "instances", "detail", "details", "words", "hand", "turn",
    "years", "decades", "century", "average", "example", "examples",
}
ADVERB_CLOSERS = {"general", "particular", "turn", "fact", "detail", "details", "vivo"}
CONNECTIVE_OPENERS = {"order", "view", "terms", "accordance", "case", "line", "front",
                      "regards", "spite", "lieu", "addition", "keeping"}
TIME_UNITS = {"second", "minute", "hour", "day", "week", "month", "year"}
QUANTIFIERS = {
    "any", "some", "this", "that", "each", "every", "all", "many", "most", "several",
    "certain", "various", "same", "other", "one", "first", "another", "whatever",
    "such", "no", "few", "more", "both", "either", "two", "three",
}
PREPS = {"at", "for", "on", "by", "to", "of", "from", "with", "per"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if prev == "in":
        if cur in CONNECTIVE_OPENERS:
            return carry, 0.6
        if cur in ADVERB_CLOSERS:
            return carry, -1.2
        return carry, 0.0
    if cur == "all" and prev == "at":
        return carry, -1.2
    if cur in TIME_UNITS and prev == "per":
        return carry, -0.7
    if cur == "end" and prev == "the":
        return carry, -0.4
    if cur in ADVERB_NOUNS or cur in ADVERB_CLOSERS:
        if prev in QUANTIFIERS or prev in PREPS:
            return carry, -0.7
        return carry, -0.2
    return carry, 0.0

programs.luna:
"""A cautious estimate from a small set of recurring word cues.

This component is almost always negligible.  It has somewhat larger negative
responses to familiar words such as “time,” “way,” and “general,” with a few
phrase-specific exceptions, so the lexical guesses are damped toward zero.
"""

READS = ()

def step(carry, prefix, upstream):
    i = prefix.position
    word = prefix.token_strings[i].strip().lower()
    previous = prefix.token_strings[i - 1].strip().lower() if i else ""
    if i and prefix.document_ids[i] != prefix.document_ids[i - 1]:
        previous = ""

    guess = 0.0
    if word == "general":
        guess = -1.9 if previous in {"in", "en"} else 0.0
    elif word == "glance" and previous == "first":
        guess = -2.5
    elif word == "order":
        guess = 0.8 if previous == "in" else -0.6
    elif word == "terms" and previous == "in":
        guess = 0.6
    else:
        guess = {
            "time": -1.2, "way": -0.45, "manner": -1.0,
            "hours": -0.8, "date": -0.4, "once": -0.4,
            "past": -0.65, "common": -0.8, "day": -0.3,
            "total": -0.7,
        }.get(word, 0.0)
    return None, 0.25 * guess + 0.001

