"""Lexical dedication, specialisation and focus, with water as an opposite cue.

Chinese 专/專 and decoded Japanese 専 are especially strong. English
'dedicated', 'devoted', 'special', 'exclusive' and focus words are weaker.
The /src directory marker is an additional, unrelated positive cue.
Rounded training means determine the sizes. State joins split words and
handles short continuations; other tokens normally get zero. Unfinished
UTF-8 prefixes and many small background responses are not modelled.
"""
READS = ()


def cue(word):
    if word in {'专', '專'}:
        return 10.0
    if word == '専':
        return 8.5
    # Chinese compounds: dedicated purpose versus professional expertise.
    if word == '专门':
        return 6.9
    if word in {'专用', '专项'}:
        return 5.5
    if word in {'专属', '专栏', '专区', '专人', '专职', '专科', '专线'}:
        return 4.6
    if word in {'专题', '专心'}:
        return 3.3
    if word.startswith(('专业', '專業', '专家', '專家')):
        return 1.1
    if word.startswith('专注'):
        return 2.1
    if word == 'dedicated':
        return 3.8
    if word == 'devoted':
        return 2.7
    if word in {'dedic', 'dedicate', 'devote'}:
        return 2.0
    if word == 'special' or word.startswith(('specializ', 'specialis')):
        return 1.5 if word == 'special' else 1.2
    if word == 'exclusive':
        return 1.8
    if word in {'exclus', 'exclusively', 'exclusivity', 'specially',
                'specialty', 'dedication', 'separate', 'reserved', 'focused'}:
        return 1.1
    if word.startswith('focus') or word in {'specifically', '-specific', 'solely'}:
        return 0.6
    if word in {'especially', 'separately', 'expert', 'experts', 'reserve'}:
        return 0.45
    if word in {'特別', '特别', 'especial'}:
        return 0.85
    if word in {'спе', 'спец', 'спеці', 'специально', 'chuyên', 'riêng'}:
        return 1.6
    if word in {'water', 'freshwater', '水'}:
        return -1.1
    if word in {'air', 'hydro', 'river', 'waters', 'underwater', 'groundwater'}:
        return -0.3
    if word == '/src':
        return 1.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, fragment = ('', '')
    if carry is not None and carry[0] == doc:
        previous, fragment = carry[1:]
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lower().lstrip('_.')
    joined = fragment + word if token and token[0].isalpha() else word
    value = cue(word)
    if joined != word and joined in {'dedicated', 'devoted', 'special', 'separate'}:
        word, value = joined, 0.8 * cue(joined)
    if word == 'special' and spelling[:1].isupper():
        value = 1.8
    if word == 'water' and not token.startswith(' '):
        value = -0.85
    if word == 'air' and not token.startswith(' ') and spelling == 'air':
        value = 0.0
    # A completed character is meaningful even when its token alone is invalid UTF-8.
    same_document = carry is not None and carry[0] == doc
    if same_document and '\ufffd' in token and prefix.text_prefixes[-1].endswith('専'):
        word, value = '専', 8.5
    if word == 'to' and previous in {'dedicated', 'devoted', 'exclusive'}:
        value = {'dedicated': 2.0, 'devoted': 1.0, 'exclusive': 0.5}[previous]
    if word == 'on' and previous.startswith('focus'):
        value = 0.28
    if word == 'in' and previous.startswith(('specializ', 'specialis')):
        value = 0.5
    if previous in {'专', '專'} and word in {'一', '车', '行', '門', '门', '用'}:
        value = 4.4 if word == '车' else 2.5
    if previous == '専' and word in {'門', '用', '務'}:
        value = 1.4 if word != '用' else 0.9
    fragment = joined[-20:] if word.isalpha() else ''
    return (doc, word, fragment), value

