programs.sol:
"""A number-introducing blank in prose, strongest in dates.

Standalone spaces receive a strength based on the preceding word's grammatical
role. Months and time/quantity expressions are strong; formulae and indentation
are weak. A remembered month boosts the blank after a date's comma or period.
Other tokens are near zero, with small offsets for months and document starts.
"""
READS = ()
MONTHS = set('''january february march april may june july august september
    october november december'''.split())
SHORT_MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
PREPOSITIONS = set('''in on around until of from about at with for between over
    after since before under into within during through throughout'''.split())

# Approximate strengths of number-introducing word classes.
GROUPS = (
    (2.35, 'in on around until'),                 # Time/date prepositions
    (1.90, 'of from about approximately roughly nearly almost circa'),  # Amounts
    (1.60, '''at with for between over after since before under into within
        during through throughout'''),
    (1.25, 'to by as than like'),
    (1.65, 'the his her its their our your'),      # Determiners
    (1.38, 'a an'),                              # Indefinite articles
    (1.00, 'this that these those and or but nor yet then is are be been being'),
    (1.50, 'was were has had have'),
    # Quantifiers, numbered references, ordinals, and measurement verbs:
    (1.35, '''only least most all each every more less fewer many several some
        any no another last next early late total exactly'''),
    (0.40, '''figure fig figs table section chapter article equation example step
        line lines group number version page volume part problem question
        theorem algorithm index item case rule claim note'''),
    (0.67, 'first second third fourth fifth sixth seventh eighth ninth tenth'),
    (1.25, '''born aged reach reaches reached add adds added adding cost costs
        weigh weighs weighing measure measures contain contains include includes
        including produce produces use uses using give gives make makes made
        score scored count counted require requires requiring spend spent'''),
    (0.85, 'year years month months week weeks day days century centuries'),
    (1.50, '''de del du des von im en el le la da dal nel à con por para un una
        em bei den dem der в на до и с по от за'''),
)
WORD_STRENGTH = {word: value for value, words in GROUPS for word in words.split()}


def blank_strength(token):
    word = token.strip().lower()
    if not word:
        return -0.02
    if word.isdigit():
        return -0.09
    if word in MONTHS:
        return 2.60
    if word in SHORT_MONTHS:
        return 2.10
    if word in {"'s", '’s'}:
        return 1.30
    if token.strip().isupper():
        return 0.03
    if word in WORD_STRENGTH:
        value = WORD_STRENGTH[word]
        if word in PREPOSITIONS | {'the', 'a', 'an'} and not token[:1].isspace():
            value -= 0.70
        return value
    if word.isalpha():
        if any('\u3400' <= c <= '\u9fff' or '\u3040' <= c <= '\u30ff'
               for c in word):
            return -0.09
        return (0.30 if word.isascii() else 0.90) if len(word) > 1 else 0.0
    if '\n' in token or '\r' in token:
        return 0.06
    if word == '.,':
        return 1.17
    if word == ',':
        return 0.85
    if ',' in word:
        return 0.44
    if word in {'.', ';', '–', '—'}:
        return 0.35
    return 0.15 if word == ':' else -0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    previous = history[-1] if history else ''
    word = previous.strip().lower()
    before = history[-2].strip().lower() if len(history) > 1 else ''
    recent_month = any(t.strip().lower() in MONTHS | SHORT_MONTHS
                       for t in history[-5:-1])
    if not history:
        value = 0.40 if token.startswith('<|') else 0.20
        if token.startswith('#'):
            value = 0.72
        elif token.strip().isdigit():
            value = -0.05
    elif token == ' ':
        value = blank_strength(previous)
        if word in MONTHS | SHORT_MONTHS:
            value += 0.50 if before in PREPOSITIONS else 0.0
            value -= 0.30 if before.isdigit() else 0.0
        elif not word.isdigit() and word:
            # Nearby grammar strengthens prose relative to formulae or code.
            if before in PREPOSITIONS | {'the', 'his', 'her', 'its', 'their'}:
                value += 0.15
            elif (not before or before.isdigit()
                    or (not any(c.isalnum() for c in before)
                        and before not in {',', '.', ':', ';', '–', '—'})):
                value -= 0.14
        if recent_month:
            if ',' in previous:
                value += 0.90
            elif word in PREPOSITIONS | {'is', 'are', 'be', 'been'}:
                value += 1.30
        if word == '.' and before in SHORT_MONTHS:
            value += 1.10
    elif token.strip().lower() in MONTHS:
        value = 0.25 * blank_strength(previous) - 0.20
    else:
        value = -0.0035
    return (doc, (*history[-4:], token)), float(value)

"""Source/basis prepositions: strongest after building or deriving something.

Large training spikes occur in these source/basis phrases.
Predict a modest positive response on `on`, `from`, and `upon`, a much
larger one in construction, basis, and origin phrases, and a weaker one
after seeing/reporting words. Include a few translated source markers
and programming uses of On/From. Most tokens get zero. Carry only a
short text tail, resetting it at document boundaries.
"""
import re

READS = ()
BUILD = set(
    'build builds building built construct constructed crafted adapted'.split()
)
BASIS = set('base based basing founded draw draws drew drawn drawing'.split())
BASIS |= set(
    'derive derives derived deriving create creates created developing'.split()
)
ORIGIN = set(
    'make makes made form formed start starts started starting'.split()
)
ORIGIN |= set(
    'take taken choose chosen select selected extract extracted'.split()
)
DEPEND = set(
    'depend depends depending dependent rely relies relying relied'.split()
)
WORK = set(
    'work works worked working act acting play played playing performed'.split()
)
REPORT = set('post posted posting report reported reply reports'.split())
SEE = set('see seen view visible look looked appear appeared displayed'.split())
INFO = set('information data comments notes'.split())
ADVERBS = set(
    'only solely largely mainly primarily partly partially directly up'.split()
)
SOURCE_MARKERS = {
    'على': 0.74, '从': 0.54, '從': 0.46, '来自': 0.59,
    '基于': 0.78, '根据': 0.38, '自': 0.32, 'から': 0.22,
    'desde': 0.68, 'từ': 0.58, 'auf': 0.18,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\r\n(._/#-').lower()
    value = SOURCE_MARKERS.get(word, 0.0)
    if word in {'on', 'from', 'upon', 'around', 'up', 'of', 'by',
                'with', 'at', 'to', 'partir', 'block', 'blocks', 'point'}:
        match = re.search(r'([A-Za-zÀà]+) *$', tail)
        prior = match.group(1) if match else ''
        previous = prior.lower()
        if previous in ADVERBS:
            words = re.findall(r'[A-Za-z]+', tail[-60:])
            previous = words[-2].lower() if len(words) > 1 else previous
        if word in {'on', 'from', 'upon'}:
            value = {'on': 0.84, 'from': 0.60, 'upon': 0.35}[word]
            if previous in BUILD:
                value = 4.7 if word == 'on' else 4.1
            elif previous in BASIS:
                value = 3.4
            elif previous in ORIGIN:
                value = 2.1 if word == 'on' else 2.65
            elif previous in DEPEND:
                value = 1.5 if word != 'upon' else 1.1
            elif previous in WORK and word == 'on':
                value = 1.6
            elif previous in REPORT and word == 'on':
                value = -0.45
            elif previous in SEE:
                value = -0.4 if word != 'on' else -0.05
            elif previous in INFO:
                value = 0.08
            elif not previous:
                value += 0.2
            elif word == 'from' and previous.endswith(('ed', 'ing')):
                value += 0.25
            if prior[:1].isupper() and value > 2.0:
                value += 0.25
            if token in {'on', 'ON'} and tail and tail[-1].isalpha():
                value = 0.23 if token == 'on' else 0.0
            elif token in {'On', ' On'}:
                value = 1.15
            elif token == 'From':
                value = 1.0
            elif token == ' From':
                value = 1.38
            elif token.strip().isupper():
                value = 0.8
            elif token[:1] in '._/' and len(token) > len(word):
                value = 1.05
            elif word == 'from' and (token.startswith('\t') or
                                     not tail or tail.endswith('\n')):
                value = 1.3
        elif word == 'around':
            if previous in BUILD:
                value = 3.4
            elif previous in BASIS:
                value = 1.6
            else:
                value = 0.15
        elif word == 'up' and previous in BUILD:
            value = 1.4
        elif word == 'of' and previous in BUILD | ORIGIN | {'composed'}:
            value = 0.75
        elif word == 'by' and previous == 'inspired':
            value = 1.3
        elif word in {'with', 'at'} and previous in ORIGIN:
            value = 0.85
        elif word == 'to' and previous == 'according':
            value = 0.39
        elif word == 'partir':
            value = 2.05 if previous in {'a', 'à'} else 1.5
        elif word in {'block', 'blocks'} and previous == 'building':
            value = 1.6
        elif word == 'point' and previous == 'starting':
            value = 1.0
    elif re.match(r'^[\s._]*(on|On|From)(?=[A-Z])', token):
        value = 1.1
