programs.sol:
"""Production/output vocabulary, not a general understanding of causation.

The largest response is to produce/production and 产/產/産 (produce or
property). Product, provide, give, generate, yield, return, and tool-response
markers have smaller responses; related industrial/property/birth words and some
production translations are included. This also recognizes code-name prefixes,
split English words, and a weak continuation onto articles and 'of'.
Everything else is zero; document boundaries reset the short word carry.
"""
import re

READS = ()


def lexical_value(token):
    word = token.strip().lstrip('._-/(@<)').lower()
    han = word.replace('產', '产').replace('産', '产')
    if '产' in han:
        if len(han) == 1:
            return 10.2 if word == '产' else 7.5
        if '品' in han:
            strength = 1.6
        elif '资产' in han or '資产' in han:
            strength = 2.1
        elif any(c in han for c in '权權房物能') or '共产' in han:
            strength = 2.5
        elif '产生' in han:
            strength = 3.1
        elif any(c in han for c in '销銷妇婦链鏈'):
            strength = 1.6
        else:
            strength = 4.3
        return strength / max(1, len(han.rstrip('的了')) - 1)
    if word in {'produ', 'reprodu'}:
        return 3.1
    if re.fullmatch(r'(re)?produc(e[ds]?|ing|tion[s]?|er[s]?)', word):
        weaker = word.startswith('re') or word.endswith(('ed', 'er', 'ers'))
        return 2.35 if weaker else 3.1
    if word in {'product', 'products'}:
        return 0.96
    if word in {'productive', 'reproductive', 'prod'}:
        return 1.5
    if word in {'return', 'returns', 'returned', 'returning'}:
        return {'return': 1.02, 'returned': 0.74}.get(word, 0.87)
    if word in {'provide', 'provides', 'provided', 'providing', '提供'}:
        return 0.72 if word == 'provided' else 0.87
    if word in {'give', 'gives', 'gave', 'giving'}:
        return 0.64
    if word == 'given':
        return 0.11
    if word in {'generate', 'generates', 'generated', 'generating'}:
        return 0.62 if word == 'generated' else 0.80
    if word in {'output', 'outputs'}:
        return 0.78
    if word in {'yield', 'yields', 'yielded', 'yielding'}:
        return 1.72 if word == 'yield' else 1.50
    # Related industrial/property vocabulary and production translations.
    if word in {'industry', 'industries', 'industrial', 'manufacturing'}:
        return 0.70
    if word in {'asset', 'assets', 'estate'}:
        return 1.0
    if word.startswith('производ'):
        return 2.4
    if word.startswith(('produk', 'üret')) or word in {'produto', 'produtos'}:
        return 1.5
    if word in {'sản', '생산', '산'}:
        return 3.7
    if word == 'نتاج':
        return 2.4
    if word in {'输出', '得出', '收益', '供', '回'}:
        return 0.65
    if word in {'孕育', '诞生', '誕'}:
        return 1.3
    if token == '<tool_response>':
        return 0.76
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_word, previous_signal = '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous_word, previous_signal = carry
    token = prefix.token_strings[-1]
    value = lexical_value(token)
    joined = token
    if token and token[0].isascii() and token[0].isalpha():
        joined = previous_word + token
        if value == 0.0 and previous_word:
            value = 0.8 * lexical_value(joined)
    word = token.strip().lower()
    gains = {'of': 0.42, 'the': 0.17, 'a': 0.095, 'an': 0.11}
    value += gains.get(word, 0.0) * previous_signal
    tail = re.search(r'[A-Za-z]+$', joined)
    trailing_word = tail.group()[-24:] if tail else ''
    return (doc, trailing_word, value), value

