programs.sol:
"""Approximate a spacing-boundary signal in Chinese/Japanese prose.

Spaces are most negative after sentence endings, less so after commas or
ordinary characters. A recent Chinese/Japanese-token average controls the
strength. Lone spaces and space-prefixed partial UTF-8 characters are more
sensitive than spaces merged into Latin words. Whole space-prefixed East
Asian characters start with a small positive offset. Indentation gets only
a near-zero offset. This captures the large boundary responses, not word-specific background.
"""
READS = ()


def asian(c):
    n = ord(c)
    return (0x3400 <= n <= 0x9fff or 0x3040 <= n <= 0x30ff
            or 0x20000 <= n <= 0x323af)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, recent = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    is_asian = any(asian(c) for c in token)
    value = 0.0
    if token.startswith(' ') and '\n' not in token:
        if token == ' ':
            value, sensitivity = 0.007, 0.93
        elif token.isspace():
            value, sensitivity = -0.005, 0.0
        elif '\ufffd' in token:
            value, sensitivity = -0.03, 1.0
        elif is_asian:
            value, sensitivity = 0.16, 0.86
        elif word.startswith(tuple('“「『（【([')):
            value, sensitivity = 0.0, 0.85
        elif word and word[0].isupper():
            value, sensitivity = 0.009, 0.55
        else:
            value, sensitivity = 0.0, 0.23
        end = previous[-1:]
        if not end or end.isspace():
            low, high = 0.0, 0.0
        elif end == '。':
            low, high = 0.55, 2.29
        elif end in '！？':
            low, high = 1.24, 1.76
        elif end in '，、：；）」』”》〉】':
            low, high = 0.2, 1.45
        elif asian(end):
            low, high = -0.26, 0.58
        elif end in '.!?,:;…．～':
            low, high = 0.04, 0.85
        else:
            low, high = 0.0, 0.24
        context = min(1.0, recent / 0.55)
        value -= sensitivity * (low + context * (high - low))
    recent = 0.8 * recent + 0.2 * float(is_asian)
    return (doc, token, recent), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:5595 (layer 0 MLP, down projection).

What it does: it fires on the word right after "the" (or " The") when that word picks out one
specific item by rank, order, position or context. Strongest for "the most", "the best",
"the past", "the world"; strong for "the same", "the first", "the last", "the right" and for
superlatives in general ("the largest", "the youngest"). Medium for ordinals and other
reference words: "the next", "the following", "the present", "the third", "the only",
"the whole", "the current", "the rest", "the top", "the bottom", "the end", "the left", "the
given". Ordinary nouns after "the" ("the plan", "the team") stay near 0. It also fires weakly
on "of" in a "the X of" phrase ("the result of", "the end of"). Other positions are 0.

Only the last two or three tokens are read; nothing is carried between positions.
"""

READS = ()

THE = {" the", " The"}

TOP = {" most", " best", " past", " world"}

HIGH = {
    " first", " same", " last", " right", " beginning", " entire", " worst",
}

SUPERLATIVE = {
    " largest", " highest", " lowest", " biggest", " smallest", " greatest", " latest",
    " earliest", " youngest", " oldest", " brightest", " finest", " shortest", " longest",
    " strongest", " nearest", " least", " hottest", " coldest", " fastest", " closest",
}

MEDIUM = {
    " next", " following", " present", " previous", " former", " latter", " second", " third",
    " fourth", " fifth", " top", " bottom", " middle", " end", " left", " wrong", " correct",
    " future", " remaining", " opposite", " above", " back", " presence", " sun", " earth",
    " United", " only", " whole", " current", " main", " final", " rest", " other", " given",
    " desired", " necessary", " corresponding", " preceding", " aforementioned", " outer",
    " upper", " early", " original", " maximum", " minimum", " initial", " proposed", " existing",
}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    t = prefix.position
    value = 0.0
    if t >= 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        if prefix.token_strings[-2] in THE:
            if cur in TOP:
                value = 2.8
            elif cur in HIGH or cur in SUPERLATIVE:
                value = 2.2
            elif cur in MEDIUM:
                value = 1.2
    if cur == " of" and t >= 2 and prefix.document_ids[-3] == prefix.document_ids[-1]:
        if prefix.token_strings[-3] in THE:
            value = 0.5
    return carry, float(value)

programs.luna:
"""Lexical approximation: selected spaced words after “the” get the largest scores."""

READS = ()

ORDER = frozenset({
    "same", "first", "second", "third", "fourth", "fifth", "sixth",
    "seventh", "eighth", "ninth", "tenth", "last", "next", "following",
    "previous", "preceding", "former", "latter", "initial", "final",
    "subsequent", "earlier", "later", "beginning", "end",
})
DEGREE = frozenset({
    "most", "least", "best", "worst", "largest", "smallest", "biggest",
    "highest", "lowest", "greatest", "maximum", "minimum", "uppermost",
    "youngest", "oldest", "strongest", "weakest", "shortest", "longest",
})
TIME = frozenset({
    "past", "present", "future", "current", "recent", "former", "latter",
    "previously", "currently", "tonight", "today", "yesterday", "tomorrow",
    "morning", "evening", "night", "day", "year", "early", "late",
})
PLACE = frozenset({
    "right", "left", "top", "bottom", "above", "below", "upper", "lower",
    "front", "back", "behind", "middle", "center", "central", "inside",
    "outside", "north", "south", "east", "west", "northern", "southern",
    "eastern", "western", "outer", "inner", "nearby", "opposite",
})
WHOLE = frozenset({
    "whole", "entire", "full", "complete", "total", "remaining", "rest",
    "all", "overall",
})
WORLD = frozenset({
    "world", "earth", "sun", "ocean", "atmosphere", "ground", "sky",
    "universe", "space", "air", "sea",
})
JUDGMENT = frozenset({
    "correct", "wrong", "exact", "proper", "accurate", "true", "false",
    "valid", "invalid",
})
STATUS = frozenset({
    "given", "aforementioned", "proposed", "specified", "desired", "original",
    "main", "necessary", "corresponding", "resulting", "selected", "appropriate",
    "required", "optimal", "only", "particular", "specific", "relevant", "existing",
    "available", "actual",
})

AFTER_THE = (1.63, 2.28, 1.04, 1.27, 0.89)
ELSEWHERE = (-0.26, -0.48, -0.02, -0.16, 0.0)
AFTER_THE_JUDGMENT = 1.75
AFTER_THE_STATUS = 0.70


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if not raw[:1].isspace():
        return None, 0.0
    word = raw.strip().casefold()
    groups = (ORDER, DEGREE, TIME, PLACE, WHOLE)
    flags = tuple(word in group for group in groups)

    previous = ""
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip().casefold()

    value = 0.0
    if previous == "the":
        if word.isalpha():
            value += 0.05
        value += sum(weight for hit, weight in zip(flags, AFTER_THE) if hit)
        if word in WORLD:
            value += 1.2
        if word in JUDGMENT:
            value += AFTER_THE_JUDGMENT
        if word in STATUS:
            value += AFTER_THE_STATUS
    else:
        value += sum(weight for hit, weight in zip(flags, ELSEWHERE) if hit)
    return None, float(value)

programs.sol:
"""Approximate a month-spelling feature, not a semantic date parser.

Title-case English months dominate the training activations. Abbreviations,
lowercase stems, some European month names, weekdays, seasons and month-name
endings are weaker cues. Endings can fire inside unrelated words too.
The next standalone space retains a date-separator response, strongest near
a document's start; a period, comma or 'of' can also retain a short response.
Other tokens predict zero. The small carry resets at document boundaries.
"""
import math

READS = ()
# Full month, three-letter abbreviation, lowercase abbreviation amplitudes.
MONTHS = {
    'January': (6.5, 5.3, 3.0),
    'February': (7.6, 5.8, 3.0),
    'March': (7.3, 3.7, 1.1),
    'April': (7.6, 5.0, 1.7),
    'May': (5.5, 5.5, 0.16),
    'June': (7.1, 3.8, 1.9),
    'July': (7.9, 4.5, 2.3),
    'August': (6.9, 4.4, 1.5),
    'September': (7.0, 4.6, 1.5),
    'October': (7.3, 5.0, 2.3),
    'November': (7.4, 4.4, 2.2),
    'December': (7.0, 4.0, 0.9),
}
ABBREVIATIONS = {m[:3]: v for m, v in MONTHS.items()}
ABBREVIATIONS['Sept'] = MONTHS['September']
DAYS = {
    'Monday': 1.3, 'Tuesday': 1.8, 'Wednesday': 1.7,
    'Thursday': 1.6, 'Friday': 1.4, 'Saturday': 1.4, 'Sunday': 0.9,
}
SEASONS = {
    'spring': 1.2, 'summer': 0.1, 'autumn': 1.2, 'fall': 0.85, 'winter': 0.4,
}


# Other familiar calendar spellings, lower in amplitude than English months.
ROMANCE_MONTHS = set("""
janvier février avril juin juillet août septembre octobre novembre décembre
enero febrero marzo abril junio julio agosto septiembre octubre noviembre
dicembre gennaio febbraio aprile giugno luglio settembre
""".split())
RUSSIAN_MONTHS = set("""
января февраля марта апреля мая июня
июля августа сентября октября ноября декабря
январь февраль март апрель май июнь
июль август сентябрь октябрь ноябрь декабрь
""".split())
GERMAN_MONTHS = set("""
Januar Februar März April Mai Juni Juli August
September Oktober November Dezember
""".split())
# Fragments shared by month names: these also respond inside unrelated words.
MONTH_ENDINGS = {
    'uary': 1.4, 'ember': 1.5, 'arch': 1.1, 'une': 0.8, 'uly': 1.5,
    'bruar': 5.2, 'brero': 2.6, 'iembre': 2.9, 'embre': 1.6,
    'illet': 2.2, 'vrier': 2.7,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, echo, abbreviated, position = '', 0.0, False, 0
    else:
        _, previous, echo, abbreviated, position = carry
    text = prefix.token_strings[-1]
    word = text.lstrip(' \t\n\r-._')
    title = word.title()
    new_echo, new_abbreviated = 0.0, False
    if word in MONTHS:
        value = MONTHS[word][0] - 0.15
        if not text.startswith(' '):
            value -= 0.4
        # Simple calendar context: a day numeral, date range, or early/late.
        before = previous.strip().lower()
        if before.isdigit():
            value += 0.5
        elif before in {'early', 'late', 'mid'}:
            value += 1.1
        elif before in {'from', 'until'}:
            value += 0.6
        elif before == 'on':
            value -= 0.4
        elif before == 'in':
            value += 0.2
        if position == 0:
            value += 1.0
        new_echo = 0.7 + 0.26 * value + 2.7 / math.sqrt(position + 1)
    elif word in ABBREVIATIONS:
        value = ABBREVIATIONS[word][1]
        if not text.startswith(' '):
            value -= 1.1 if word in {'Oct', 'Dec'} else 0.2
        if text.startswith('-'):
            value += 1.0
        new_echo = 1.15 + 0.18 * value + 1.9 / math.sqrt(position + 1)
        new_abbreviated = True
    elif title in ABBREVIATIONS:
        value = ABBREVIATIONS[title][2]
        if word.isupper():
            value = 0.4 * ABBREVIATIONS[title][1]
            if word == 'JUL':
                value = 4.2
            elif word == 'DEC':
                value = 1.0
        elif not text.startswith(' ') and word.lower() != 'may':
            value *= 0.6
            if word == 'jan':
                value = 0.85
        if word == 'sept':
            value = 2.5
    elif title in MONTHS:
        value = 0.65 * MONTHS[title][0]
        if word == 'march':
            value = 2.6
        new_echo = 0.35 * value
    elif word.lower() in ROMANCE_MONTHS:
        value, new_echo = 4.0, 1.2
        if word.lower().endswith('embre'):
            value = 4.4
    elif word == 'Mai':
        value = 0.7
    elif word.lower() in RUSSIAN_MONTHS:
        value, new_echo = 4.8, 1.6
    elif word in GERMAN_MONTHS:
        value, new_echo = 3.8, 1.2
    elif (word in {'мар', 'ноя'} or len(word) >= 4
          and any(m.startswith(word.lower()) for m in RUSSIAN_MONTHS)):
        value = 2.2 if word == 'мар' else 4.0
    elif word in MONTH_ENDINGS and text == word:
        value = MONTH_ENDINGS[word]
        new_echo = 0.4 * value
    elif word in {'mars', 'mai', 'mayo'}:
        value = 1.0
    elif word in DAYS:
        value = DAYS[word]
        new_echo = 0.3
    elif word.lower() in SEASONS:
        value = SEASONS[word.lower()]
        new_echo = 0.8
    elif word in {'月', '월'}:
        value = 1.5
    elif word.endswith('月') and set(word[:-1]) <= set('一二三四五六七八九十'):
        value = 2.5
    elif word in {'春', '秋'}:
        value = 1.0
    elif text == ' ':
        value = echo
    elif text == '.' and abbreviated:
        value, new_echo = 0.55, 0.55 * echo
    elif text == ',' and echo > 0.0:
        value, new_echo = 0.1, 0.4 * echo
    elif word == 'of' and echo > 1.5:
        value, new_echo = 2.0, 1.4
    else:
        value = 0.0
    next_carry = (doc, text, new_echo, new_abbreviated, position + 1)
    return next_carry, float(value)

programs.haiku:
"""Month-name detector (layer-0 MLP down_proj, component 5596).

What it responds to: month names in running text. It fires hardest on capitalised English
month names as they appear in dates ("... on 29 October", "June 2006", "Joined: 19 Feb 2007"),
somewhat less on capitalised abbreviations ("Jan", "Sep"), less on month names in other
languages, and weakly on weekday names, seasons and the Chinese/Korean month character.
It also fires moderately on the space token right after a month name, before the day or
year, since digits are tokenised one at a time: "March 2019" is "March", " ", "2", "0", ...
The lowercase modal verb "may" does not count. Everything else is about zero.

The program is stateless: it looks only at the current token and the one before it.
The numbers are typical activations for each class, averaged over training text.
"""

READS = ()

MONTHS = {
    "january", "february", "march", "april", "may", "june", "july",
    "august", "september", "october", "november", "december",
}
ABBREVIATIONS = {"jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept", "oct", "nov", "dec"}
OTHER_LANGUAGE_MONTHS = {
    "janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre",
    "octobre", "novembre", "décembre", "januar", "februar", "märz", "juni", "juli", "oktober",
    "dezember", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto",
    "setembro", "outubro", "janeiro", "fevereiro", "março", "maio", "junho", "julho",
    "gennaio", "febbraio", "aprile", "giugno", "luglio", "settembre", "ottobre", "dicembre",
    "января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября",
    "октября", "ноября", "декабря",
}
CJK_MONTH_CHARACTERS = {"月", "월"}
WEEKDAYS = {"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"}
SEASONS = {"spring", "summer", "autumn", "fall", "winter"}


def is_month(text):
    """True if the token (spaces stripped) is a month name, abbreviation or foreign name."""
    lower = text.lower()
    return lower in MONTHS or lower in ABBREVIATIONS or lower in OTHER_LANGUAGE_MONTHS or text in OTHER_LANGUAGE_MONTHS


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    capitalised = word[:1].isupper() and not word.isupper()

    # the space between a month name and the day or year after it
    if raw == " " and len(prefix.token_strings) > 1 and is_month(prefix.token_strings[-2].strip()):
        return carry, 2.8
    if word == "may":
        return carry, 0.0  # the lowercase modal verb, not the month
    if lower in MONTHS:
        return carry, 6.9 if capitalised else 3.0
    if lower in ABBREVIATIONS:
        return carry, 4.3 if capitalised else 1.2
    if word in OTHER_LANGUAGE_MONTHS:
        return carry, 3.0
    if word in CJK_MONTH_CHARACTERS or lower in WEEKDAYS:
        return carry, 1.4
    if lower in SEASONS:
        return carry, 0.7
    return carry, 0.0

programs.luna:
"""Recognize month and weekday words, plus the space after a month.

Layer 0's down-projection component is most active on written month names,
especially in dates.  Smaller responses accompany weekday and season words.
"""

READS = ()

MONTHS = {
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
}
OTHER_MONTHS = {"mayıs", "juni", "juli", "octobre", "febrero"}
ABBREVIATIONS = {
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep",
    "sept", "oct", "nov", "dec",
}
WEEKDAYS = {
    "monday", "tuesday", "wednesday", "thursday", "friday",
    "saturday", "sunday",
}
SEASONS = {"spring", "summer", "fall", "autumn", "winter"}
PUNCTUATION = ".,:;!?)]}\"'`-–—"


def _word(text):
    """Return a single word token without its surrounding punctuation."""
    return text.strip().strip("([{" + PUNCTUATION).strip().lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_doc, old_tail = carry if carry is not None else (doc, "")
    if old_doc != doc:
        old_tail = ""

    stripped = token.strip()
    starts_word = bool(stripped) and stripped[0].isalpha()
    joins_word = starts_word and token[:1].isalpha()
    if joins_word and old_tail:
        current = old_tail + stripped
        is_continuation = True
    else:
        current = stripped
        is_continuation = False

    word = _word(current)
    first_letter = next((char for char in stripped if char.isalpha()), "")
    if word == "may":
        # Lower-case "may" is usually the modal verb, not the month.
        value = 5.8 if first_letter.isupper() else 0.5
    elif word in MONTHS:
        value = 2.7 if is_continuation else 6.7
    elif word in OTHER_MONTHS:
        value = 2.0 if is_continuation and word == "octobre" else (
            2.7 if is_continuation else 3.0
        )
    elif word in ABBREVIATIONS:
        value = 4.4
    elif word in WEEKDAYS:
        value = 1.5
    elif word in SEASONS:
        value = 0.85
    elif token == " " and old_tail.lower() in MONTHS | ABBREVIATIONS:
        value = 2.7
    elif word == "月":
        value = 2.0
    else:
        value = 0.0

    letters = []
    for char in token:
        if char.isalpha():
            letters.append(char)
        else:
            letters.clear()
    tail = "".join(letters)[-16:]
    return (doc, tail), float(value)

