    ('homes', 'home house hotel', (.4, .8, .25)),
    ('body', 'body head hand hands face eyes skin heart leg legs arms feet '
     'hair', (.09, .3, .05)),
    ('data', 'data model models code program file files information',
     (.22, .3, .08)),
    ('computers', 'computer browser server laptop', (1.2, .8, .65)),
)
NOUNS = {w: scores for name, words, scores in OWNERSHIP
         for w in words.split()}
CHINESE_COLLECTIVES = set('国國省市县縣党黨军軍校司行厅廳')
ADJECTIVES = set(('own new old little big free first last previous next main '
                  'most best good personal dear other recent current').split())
FUNCTION = set(('a an the and or but in on at for to of with from by is are '
                'was were be been have has had it we i you this that these '
                'those not').split())
