    r'\\(?:frac|math|sum|int|begin|end|left|right|theta|alpha|lambda)\b'
    r'|\b(?:equation|polynomial|integer|matrix|theorem|lemma|proof|'
    r'derivative|integral|vertices|subspace)\b')
CODE = re.compile(r'\bfunction\s+\w+\s*\(|\b(?:foreach|if|while)\s*\('
                  r'|->|=>|<\?php|\$[A-Za-z_]\w{2,}')
