    if '$$' in token:
        return -.06
    if token.endswith(('}$', ')$')):
        return .07
    if not token.rstrip().endswith('$'):
        return -.04
    if MATH.search(context):
        return -.05
    if CODE.search(context):
        return .5
    if MONEY.search(context):
        return .6
