"""A paragraph-break signal that adapts to document structure.

Predict zero on ordinary text. Tokens containing two or more newlines
receive mostly negative values, stronger early in a document or after
few prior paragraph breaks. Code terminators and quotation endings are
stronger than prose periods, commas, or colons. Token-boundary whitespace,
preceding token length, chat headers, and thinking delimiters provide
small corrections.
The counters distinguish single newlines from blank-line tokens.
All counters reset at a document boundary; no future text is inspected.
"""
from math import log1p, sqrt

READS = ()
PUNCTUATION = {
    '.': 0.02, ':': 0.09, ',': 0.03, '?': 0.05,
    '{': -0.23, '}': -0.23, ']': -0.15, ')': -0.15,
    '`': -0.15, '!': -0.23, '-': -0.27,
}
NORMALIZE_PUNCTUATION = str.maketrans('。．：，？！', '..:,?!')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, paragraph_breaks, single_breaks, previous = 0, 0, 0, ''
    else:
        _, position, paragraph_breaks, single_breaks, previous = carry
    token = prefix.token_strings[-1]
    breaks = token.count('\n')
    ending = token.split('\n', 1)[0].strip()
    ending = ending.translate(NORMALIZE_PUNCTUATION)
    value = 0.0
    if breaks >= 2:
        onset = -1.10
        if not ending:
            if any(c in ' \t\r' for c in token):
                value, onset = 0.11, -0.88
            else:
                value, onset = -0.04, -1.83
        elif ending.endswith(';'):
            value = -0.45 if len(ending) == 1 else -0.42
        elif ending.endswith(('"', "'")):
            value = -0.43 if len(ending) == 1 else -0.13
        elif ending == '...':
            value = -0.37
        else:
            value = PUNCTUATION.get(ending[-1], -0.27)
            if len(ending) > 1:
                value -= 0.14
        value += onset / sqrt(position + 1)
        value -= 0.62 / sqrt(paragraph_breaks + 1)
        value += 0.26 / sqrt(single_breaks + 1)
        value -= 0.047 * log1p(len(previous.strip()))
        if position == 0:
            value += 1.49
        elif position == 1:
            value += 0.77
        if breaks >= 3:
            value -= 0.20
        if breaks >= 4:
            value += 0.15
        if '\r' in token:
            value -= 0.21
        if previous == '<think>':
            value += 0.28 / sqrt(paragraph_breaks + 1)
        elif previous == '</think>':
            value += 0.54 / sqrt(paragraph_breaks + 1)
        paragraph_breaks += 1
    elif breaks == 1:
        if ending:
            base, onset, repeat, start = 0.010, -0.070, 0.026, 0.181
        elif token.startswith('\n'):
            base, onset, repeat, start = 0.064, -0.401, -0.069, 0.384
        else:
            base, onset, repeat, start = 0.038, -0.276, 0.031, 0.124
        value = base + onset / sqrt(position + 1)
        value += repeat / sqrt(paragraph_breaks + single_breaks + 1)
        if position == 0:
            value += start
        if '\r' in token:
            value -= 0.026
        if (prefix.position >= 2 and prefix.document_ids[-3] == doc
                and prefix.token_strings[-3] == '<|im_start|>'):
            if previous == 'user':
                value = -0.42 if position == 2 else -0.02
            elif previous == 'assistant':
                value = -0.33 if position == 2 else 0.05
        single_breaks += 1
    return (doc, position + 1, paragraph_breaks, single_breaks, token), float(value)

