READS = ()

# Chinese: source, fountainhead, origin/water source, open source,
# power-source, energy-source, and from/original respectively.
CHINESE = (
    ({'源'}, -7.7),
    ({'源头'}, -5.0),
    ({'来源', '来源于', '水源', '源源'}, -4.0),
    ({'开源', '源于', '源自'}, -3.3),
    ({'电源'}, -2.7),
    ({'能源'}, -1.8),
    ({'从', '從', '来自', '来自于', '原'}, -1.0),
)


def lexical_value(token):
    text = token.strip()
    word = text.lstrip('._/-(\"[')
    lower = word.lower()
    mark = text[:len(text) - len(word)]
    if lower in {'source', 'ource'}:
        if mark.startswith(('.', '/', '(')):
            return -5.0
        if word == 'Source':
            return -6.9 if token.startswith(' ') else -7.4
        if word.isupper():
            return -5.8
        return -6.5 if token.startswith(' ') else -5.9
    if lower in {'sources', 'ources'}:
        if lower == 'ources' and word.isupper():
            return -1.3  # Continuation of RESOURCES rather than SOURCES.
        return -3.0 if mark == '/' else -5.4
    if lower in {'sourced', 'sourcing', 'ourced', 'ourcing'}:
        return -3.3
    if lower == 'src':
        return -2.8 if mark == '/' else -2.4
    if lower in {'github', 'ithub'}:
        return -1.7 if token == 'github' else -1.0
    if lower == 'from':
        return -1.0 if token == ' from' else -1.2
    if lower in {'origin', 'origins', 'originate', 'originated', 'originating'}:
        return -1.2
    if lower in {'orig', 'original', 'originally', 'plagiar'}:
        return -0.9
    if lower == 'supply':
        return -0.65
    for words, value in CHINESE:
        if text in words:
