        return -3.5  # Russian and Vietnamese source words.
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = lexical_value(token)
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-2] == prefix.document_ids[-1])
    previous = prefix.token_strings[-2].strip().lower() if same_document else ''
    if token == ' from':
        if previous in {'apart', 'away', 'free'}:
            value = -0.25
        elif previous in {'different', 'differ', 'removed', 'separated', 'aside'}:
            value = -0.45
        elif previous in {'resulting', 'results', 'extracted', 'derived', 'isolated'}:
            value = -0.65
    elif token == ' source' and previous == 'open':
        value = -5.1
    return None, float(value)

