programs.haiku:
"""Layer-0 MLP feature: "the letter a inside a word fragment".

Component layers.0.mlp.down_proj:5603 switches on for tokens that spell the letter
a (in any case, with or without accents, and its Greek and Cyrillic look-alikes),
when the token is a piece of a word or name rather than a common function word.
Short fragments fire most (ag, am, ash, AC, name pieces); long whole words fire
less; a few function words containing a (and, that, was, all, about, ...) do not
fire at all. Chinese characters (CJK ideographs) fire at a moderate level.
Everything else (spaces, punctuation, digits, most other letters) stays at 0.

The program reads only the current token (it is stateless). The layer-0 MLP
sees mostly the token's own identity, so a token-level rule captures most of it.
"""

import unicodedata

READS = ()

# Common English function words that contain the letter a but do not fire.
FUNCTION_WORDS = frozenset(
    """a an and are was were that all any also about after again against among
    around along above across already always another because each than what many
    may""".split()
)


def letters(text):
    """Lower-case letters of a token, accents stripped, Greek alpha and Cyrillic
    a read as Latin a."""
    out = []
    for ch in text:
        if ch.isalpha():
            base = unicodedata.normalize("NFKD", ch)[0].lower()
            out.append("a" if base in ("а", "α") else base)
    return "".join(out)


def is_cjk(text):
    return any("一" <= ch <= "鿿" for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if is_cjk(token):
        return carry, 0.27
    if not token.isalpha():
        return carry, 0.0
    spelled = letters(token)
    if "a" not in spelled or token.lower() in FUNCTION_WORDS:
        return carry, 0.0
    n = len(spelled)
    if n == 1:
        value = 0.35
    elif n <= 4:
        value = 0.95  # short word fragment: ag, am, ash, AC, ...
    elif n <= 6:
        value = 0.7
    else:
        value = 0.45  # long whole word
    return carry, value

