"""An approximate spelling-based encoding/enclosing signal.

The fragment 'enc' and encoding words produce the largest estimates. Enclosing
and encapsulating words are strong too; encouragement, encounters, decoding,
wrapping and sealing are weaker. A few Chinese equivalents are included.
Split enc-words retain a signal on their next pieces. Form feeds are positive,
and 'continue to' is negative. Everything else receives zero. These rules
capture lexical responses, not a general understanding of encoding or enclosure.
"""
READS = ()

# Spelling families: encoding first, then enclosing and other enc- words.
FAMILIES = (
    (('encoding',), 4.85),
    (('encoded',), 3.8),
    (('encode',), 4.0),
    (('enclosed', 'enclosing', 'enclose'), 3.6),
    (('enclosure',), 2.3),
    (('encaps',), 2.5),
    (('encyclop',), 1.6),
    (('encour',), 1.1),
    (('encounter',), 0.95),
    (('encore',), 0.55),
)

# Weaker related words and fragments, grouped by familiar word families.
RELATED = (
    (('enco', 'enci'), 1.0),
    (('oding', 'oded'), 0.7),
    (('sealed', 'sealing'), 0.85),
    (('seal', 'closed', 'surrounded', 'surround'), 0.4),
    (('packaging', 'packing', 'emb'), 0.6),
    (('wrap', 'wrapped'), 0.8),
    (('封', '编码', '編碼'), 4.2),  # seal; encoding
    (('封闭', '封装', '密封'), 1.8),  # enclosing; encapsulation; sealing
    (('编', '編', '鼓励', '包装'), 0.9),  # coding; encouragement; packaging
    (('围', '圈'), 0.55),  # surrounding; circle
)


def lexical_value(word, token):
    if word == 'enc':
        if token == 'enc':
            return 3.45
        if token.strip() == 'Enc':
            return 4.3 if token[:1].isspace() else 5.0
        return 5.0
    if word.startswith('encoder'):
        return 4.3 if token.startswith('Encoder') else 3.4
    for stems, value in FAMILIES:
        if word.startswith(stems):
            return value
    if word.startswith('decode'):
        return 1.5 if token == token.strip() else 1.0
    if word.startswith(('decoding', 'coding')) or word == 'coded':
        return 0.8
    if word.startswith(('wrapper', 'wrapping')):
        return 0.5
    if word.startswith(('embed', 'encrypt')):
        return 0.8
