    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    scale = 1.0 if not previous else carry[2]
    surface = token.strip().lstrip('._-/(')
    word = surface.lower()
    value = lexical_value(word, token)
    if token[:1].isspace() or not previous:
        joined, scale = word, 1.0
    else:
        joined = previous + word
        # Recognize a split word from its spelling, without seeing later tokens.
        if previous.endswith('enc') or previous == 'en':
            if 'encoding' in joined:
                value = 5.1 * scale
            elif 'encoder' in joined:
                value = 3.8 * scale
            elif 'encode' in joined:
                value = 4.1 * scale
            elif joined.startswith(('enclos', 'encaps', 'encour')):
                value = 2.4 * scale
        elif previous.startswith('encour') and joined.startswith('encour'):
            value = 1.8 * scale
        elif previous.startswith('encaps') and joined.startswith('encaps'):
            value = 1.2 * scale
    if word == 'to' and previous in ('continue', 'continued', 'continuing'):
        value = -0.65
    # Encoding inside a longer mixed-case identifier is a weaker signal.
    if word.startswith('encod') and any(c.isupper() for c in surface[1:]):
