    """Lowercase word pieces of a token, splitting camelCase: '.setItem' -> ['set', 'item']."""
    return [w.lower() for w in re.findall(r"[A-Z]?[a-z]+|[A-Z]+|[0-9]+", token)]


def level(token):
    parts = pieces(token)
    if any(p in ("set", "sets") for p in parts):
        return 4.0
    if parts and parts[0] in FORM_LEVEL:
        return FORM_LEVEL[parts[0]]
    if any("set" in p for p in parts):
