"""Programming operators and expression-ending punctuation, not ordinary prose.

A short text window supplies soft evidence for code: an open function call,
indentation with assignment/braces, or a member/underscored identifier.
Separators and closing brackets follow that evidence. Spaced boolean operators
are strong on their own; loop membership and alias keywords need their syntax.
These are approximate activation sizes. No model weights or token-id tables
are used. LaTeX math notation weakens code evidence and binary-operator
responses. The text window resets between documents.
"""
import re
READS = ()

# Typical strengths; syntax below scales each operation's response.
BINARY = {
    '&&': 3.0, '||': 3.25, '==': 1.9, '!=': 2.1,
    '===': 3.0, '!==': 3.4, '<<': 3.3,
    '+=': 1.5, '-=': 1.5, '*=': 1.5, '/=': 1.5,
}
SYMBOLS = {
    '+': 1.3, '-': .65, '*': 2.0, '/': .9, '%': 1.0,
    '<': 1.5, '>': 2.1, '<=': 1.8, '>=': 1.8, '>>': 1.8,
    '|': 1.5, '&': .65, '!': 1.2, '?': 2.7, '??': 3.2,
}
LOOP = re.compile(r'\b(?:for|foreach)\s*\(?\s*'
                  r'(?:(?:var|let|const|int)\s+)?[\w$]+(?:\s*,\s*[\w$]+)*$')
CALL = re.compile(r'\b[A-Za-z_]\w{2,}\(')


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    recent, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    carry = (doc, (recent + token)[-160:], token)
    t, p = token.strip(), previous.strip()
    if not (t in BINARY or t in SYMBOLS or t in {'in', 'as', 'else', 'import',
            ',', ':', '[', '][', ']', ']]', ';', '=>', '::'}
            or t.startswith('()') or re.fullmatch(r'[)\]]+[.,:*/+%-]?', t)
            or (t and not t.strip('\\'))):
        return carry, 0.0
    recent = re.sub(r'<\|[^|]*\|>', '', recent)
    recent = recent.replace('\\n', '\n').replace('\\t', '\t')
    line = recent.rsplit('\n', 1)[-1]
    match = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', recent)
    word = match[0] if match else ''
    indented = bool(re.match(r'^(?: *\t| {2,}|[+-]\s{2,}| *\d+\t)', line))
    marks = sum(recent[-100:].count(c) for c in '={};_')
    call = any(recent[m.end():].count('(') >= recent[m.end():].count(')')
               for m in CALL.finditer(recent))
    keyword = bool(re.search(r'\b(if|for|while|return|def|class|var|let|const|new)\b', line))
    spaced, newline = token[:1].isspace(), '\n' in token
    code = (.7 + .3 * indented) if call else (
        .65 if indented and marks else .2 if indented else .15 if marks > 2 else .01)
    if word and (('_' in word) or recent.endswith('.' + word)):
        code = max(code, .8)

    maths = bool(re.search(r'\\(?:frac|left|right|sqrt|sum|mathrm)\b', recent))
    if maths:
        code *= .3

    if t in BINARY:
        strength = (.46 + .20 * indented + .15 * keyword) if spaced else .18
        if not p or p in {'=', '+', '-', '|', '||', '//'}:
            strength *= .2
        if p.endswith('()') or word in {'null', 'nil', 'None'}:
            strength *= 1.25
        return carry, BINARY[t] * strength * (.3 if maths else 1.0)
    if t in SYMBOLS:
        strength = code if spaced else code * .2
        if spaced and t in {'<', '>', '<=', '>='} and re.search(
                r'\b(?:if|while)\s*\(?[^;{}:\n]*$', line):
            strength = max(strength, .7)
        if p.endswith('()') or p.endswith(('"', "'")):
            strength = max(strength, .9 if spaced else .1)
        if not p or p in {'=', '+', '-', '*', '|', '||', '//'}:
            strength *= .1
        if t == '*' and word in {'int', 'char', 'void', 'float', 'double'}:
            strength *= .25
        return carry, SYMBOLS[t] * strength
    if spaced and t == 'in':
        if LOOP.search(recent):
            strong = indented or marks or '[' in line or len(word) == 1
            return carry, (3.2 if len(word) == 1 else 2.55) if strong else .3
        return carry, .8 * code if keyword else 0.0
    if spaced and t == 'as':
        binding = re.search(r'\b(import|except|with|foreach)\b[^:\n]*$', line)
        valid = binding and (indented or '(' in line or
                             line.lstrip().startswith(('import', 'except', 'with', 'foreach')))
        return carry, 1.9 if valid else .15 * code
    if spaced and t == 'else':
        return carry, 1.5 * code
    if spaced and t == 'import':
        return carry, 1.0 if re.search(r'\bfrom\s+[\w.]+$', line) else .3 * code
    if t.startswith('()'):
        value = .02 if ';' in t else .1 if newline else 1.1 if t.endswith('.') else .65
        return carry, value
    if t == ',':
        return carry, code * (.5 if newline else 1.0)
    if t == ':':
        return carry, code * (1.3 if spaced else .5)
    if t in {'[', '][', ']', ']]'}:
        return carry, code * (.1 if newline else .5)
    if re.fullmatch(r'[)\]]+[.,:*/+%-]?', t):
        scale = 1.0 if t.endswith('.') else .65
        return carry, code * scale * (.4 if newline else 1.0)
    if t == ';':
        return carry, code * (.04 if newline else .3)
    if t == '=>':
        return carry, .36 if spaced else .1
    if t and not t.strip('\\'):
        return carry, .4 if len(t) > 1 else .04
    if t == '::':
        return carry, -.12
    return carry, 0.0

