programs.sol:
"""A negative marker for directory/direction words and their token fragments.

Directories, 'dir', and file-system operations give the largest response;
movement directions and folders are weaker. Word tokens, code fragments, and
capitalized forms differ in strength. 'Working directory' is especially strong.
Translations and spelling echoes are included; other tokens give zero.
This deliberately leaves out the many weak, unrelated lexical responses.
"""

READS = ()

DIRECTORY_QUERIES = {'listdir', 'readdir', 'opendir', 'isdir', 'isdirectory'}
DIRECTORY_UTILITIES = {'mkdir', 'mkdirs', 'chdir', 'makedirs', 'getcwd', 'dirent'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lstrip('._-/(').lower()
    space = token.startswith(' ')
    previous = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    value = 0.0

    if word in ('directory', 'irectory'):
        if spelling.isupper():
            value = -4.3
        elif word == 'irectory':
            value = -4.9
        elif space and spelling.islower():
            value = -6.2
            if previous in ('working', 'current'):
                value = -6.8
            elif previous in ('a', 'this', 'that', 'parent', 'root'):
                value = -5.7
        elif spelling.lstrip('._-/(') == 'Directory':
            value = -6.3
        else:
            value = -4.8
    elif word == 'directories':
        value = -4.8 if space else -3.0
    elif word in ('dir', 'dirname'):
        value = -4.4
        if space and spelling.islower():
            value = -3.6
        elif spelling.startswith('('):
            value = -3.1
        directory_prefix = previous.lstrip('.=(/')
        if word == 'dir' and directory_prefix in ('root', 'src', 'tmp', 'pkg'):
            value = -4.9
    elif word == 'dirs':
        value = -3.2
    elif word in ('direction', 'directions', 'irection'):
        value = -3.35 if space and spelling.islower() else -2.9
        if word == 'directions' and not space:
            value = -2.35
    elif word in ('dire', 'directional', 'irectional'):
        value = -1.6
    elif word in ('folder', 'folders'):
        value = -1.75
    elif word in DIRECTORY_QUERIES:
        value = -3.6
    elif word in DIRECTORY_UTILITIES:
        value = -2.3
    elif word in ('kdir', 'mdir'):
        value = -3.2
    elif word == 'cwd':
        value = -1.9 if space else -1.2
    elif word in ('director', 'directors', 'directive', 'directives', 'circular'):
        value = -0.6
    elif word in ('direct', 'directed', 'circle', 'axis'):
        value = -0.25
    elif word in ('disk', 'disks'):
        value = -0.75
    elif spelling in ('目录', '目錄'):
        value = -5.4
    elif spelling.endswith('方向'):
        value = -2.15
    elif spelling in ('录', '錄'):
        value = -4.4 if previous == '目' else -1.65
    elif spelling == '目':
        value = -0.7
    elif spelling in ('盘', '盤'):
        value = -0.75
    elif word in ('каталог', 'dirección'):
        value = -1.4
    elif word == 'направ':
        value = -0.9

    return None, value

programs.luna:
"""Approximate the negative pulses on direction/directory wordpieces.

It uses smaller pulses for a few related direction and file/path terms, and
otherwise returns the component's near-zero average.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()

    if "directory" in token or token in {"folder", "folders"}:
        value = -5.0 if "directory" in token else -1.0
    elif "direction" in token:
        value = -3.0
    elif "director" in token:
        value = -0.8
    elif token == "dir":
        value = -4.0
    elif "circular" in token:
        value = -0.8
    elif "направ" in token:
        value = -0.8
    elif token == "disks":
        value = -0.9
    else:
        value = -0.00258

    return None, float(value)

programs.sol:
"""Lexical cues for truth, deception, and concealed information.

The strongest negative cues are truth and lies, including some Chinese
translations; weaker ones concern secrecy, honesty, evidence, and guilt.
Some words of qualification/knowing give small positive responses.
Homographs also fire: 'lies' need not mean dishonesty. Nearby reporting
verbs strengthen 'the truth', while technical 'ground truth' is weaker.
Word fragments and capitalization are handled separately, as are
conversation delimiters and capitalized Boolean literals. A weak negative
continuation extends onto connecting words
after these cues. All memory resets at a document boundary.
"""
READS = ()

# Veracity and social-trust vocabulary, grouped by approximate strength.
GROUPS = (
    (0.1, {'likely', 'probably', 'apparently', 'really', 'know', 'knew', 'sure'}),
    (0.25, {'basically', 'effectively', 'essentially', 'accuracy'}),
    (0.4, {'reasonably', 'presumably', 'arguably', 'expressly'}),
    (-3.0, {'truth', 'truthful', '真相', '谎言'}),
    (-2.1, {'deceit', 'falsehood', '虚假', '隐瞒'}),
    (-1.8, {'lie', 'lies', 'truths'}),
    (-1.6, {'deception', '秘密', '谣言', '骗', '欺骗'}),
    (-1.3, {'lying', 'lied', 'honesty', 'honestly', 'dishonest',
            'deceptive', 'hoax', 'untrue', 'liar', 'rumor', 'slander', '诚实'}),
    (-1.05, {'honest', 'secret', 'secrets', 'secretly', 'concealed',
             'rumors', 'rumours', 'gossip', 'hypocrisy', 'prank',
             '真实', '事實', '道歉', '悄悄', '真實', '真理', 'verdade'}),
    (-0.85, {'guilt', 'betrayal', 'misleading', 'ashamed', 'embarrassing',
             'shameful', 'deceived', '隐私', '偷偷', '偷', '真诚', '愧'}),
    (-0.65, {'hidden', 'hiding', 'conceal', 'secrecy', 'confidentiality',
             'conspiracy', 'scandal', 'falsely', 'cheating',
             '本当', '実は', '秘', '隐藏', 'verdad', '사실'}),
    (-0.5, {'reality', 'fake', 'proof', 'fraud', 'fraudulent', 'theft',
            'buried', 'genuine', 'shame', 'sincere', 'sincerity',
            'forgiveness', 'facts', '事实', '证据', '事实上'}),
    (-0.4, {'evidence', 'factual', 'doubt', 'suspicion', 'privacy',
            'confidential', 'hide', 'hides', 'stealing', 'betrayed',
            'authentic', 'trustworthy', '话', '现实', '其實'}),
    (-0.25, {'guilty', 'testimony', 'confess', 'steal', 'truly', 'confession'}),
)
STRENGTH = {word: value for value, words in GROUPS for word in words}
REPORTING = {'tell', 'telling', 'told', 'reveal', 'revealed', 'revealing',
             'speak', 'speaking'}
MARKERS = {
    '<tool_call>': 0.26, '</tool_call>': 0.45,
    '<tool_response>': 0.05, '</tool_response>': 0.11,
    '<think>': 0.16, '</think>': 0.02,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    raw_word = token.strip(' \t\r\n_-.(')
    word = raw_word.lower()
    previous = history[-1] if history else ''
    value = STRENGTH.get(word, 0.0)
    boundary = token[:1].isspace() or token[:1] in '_-.('

    if word in {'lie', 'lies'}:
        if not boundary:
            value *= 0.33 if word == 'lie' else 0.2
        elif raw_word[:1].isupper():
            value *= 0.65
    elif word == 'lying' and not boundary:
        value *= 0.1
    elif word == 'secret':
        if token == 'secret':
            value = -0.65
        elif raw_word == 'Secret':
            value = -0.6 if boundary else -0.9
    elif word == 'proof' and raw_word[:1].isupper():
        value = -0.3

    if word == 'truth':
        value = -2.6
        if raw_word == 'Truth':
            value = -3.2
        if previous == 'ground':
            value = -2.0
        elif previous == 'the':
            value = -3.1
            if any(w in REPORTING for w in history[:-1]):
                value = -4.3
        if not history:
            value = -5.1
        elif token.startswith('_'):
            value = -1.65
    elif token == 'fully' and previous == 'truth':
        value = -3.2
    elif word == '谎':
        value = -2.5
    elif token == ' false':
        value = -0.2
    elif token == ' fact':
        value = -0.09

    # Continue the lexical cue onto a following relation/complement word.
    continuation = min(0.0, STRENGTH.get(previous, 0.0))
    if boundary:
        if word in {'of', 'about', 'behind'}:
            value += 0.3 * continuation
        elif word in {'to', 'for', 'with'}:
            value += 0.18 * continuation
        elif word in {'in', 'on', 'is', 'that'}:
            value += 0.08 * continuation
    if token == 'y' and previous == 'truth':
        value = -1.3

    if token in {' True', 'True'}:
        value = 0.19
    elif token in {' False', 'False'}:
        value = 0.09

    if token in MARKERS:
        value = MARKERS[token]
    elif token == '<|im_start|>':
        value = -0.14 if history else 0.22
    elif token == '<|im_end|>':
        if not history:
            value = 0.12
        else:
            after_tool = previous in {'</tool_call>', '</tool_response>'}
            value = 0.0 if after_tool else -0.12

    return (doc, (*history[-3:], word)), float(value)

programs.luna:
"""Approximate a sparse negative response to words about truth and evidence,
or about lies and rumors. The real response is much more context-dependent."""

READS = ()

TRUTH_AND_EVIDENCE = {
    "truth", "truths", "truthful", "truthfulness", "fact", "facts",
    "evidence", "proof", "honesty", "honest", "veracity", "genuine",
    "reality", "verdad", "実は", "本当", "证据", "事实",
}

DECEPTION_AND_SECRECY = {
    "lie", "lies", "lied", "lying", "falsehood", "falsely", "fake",
    "fraud", "fraudulent", "deceive", "deception", "dishonest",
    "secret", "hidden", "guilt", "guilty", "rumor", "rumors",
    "rumour", "rumours", "gossip", "conspiracy", "theories", "doubt",
    "disguised", "谣言", "谣",
