programs.sol:
"""Approximate an information-presentation signal from words and short phrases.

Positive responses mark explaining, giving, including, identifying and calling
attention to information. Prepositions inherit the signal in familiar phrases
such as 'point out', 'look at', 'focus on', and 'in terms of'. The small lexical
classes distinguish verbs from content nouns; past forms can be weaker.
The lexicons also include Chinese reporting/giving words. Unlisted tokens
are nearly silent. Only the previous token is remembered, resetting by document.
The fixed response sizes summarize training observations, not probabilities.
"""
READS = ()

# Meaning, response, and ordinary English base words in that class.
LEXICON = (
    ('emphasis', 1.13,
     'highlight emphasize reiterate acknowledge proclaim underscore'),
    ('explicit_reference', 0.79,
     'mention cite outline argue contend conclude insist identify recognize '
     'illustrate demonstrate assert'),
    ('reporting', 0.48,
     'say state indicate suggest explain describe discuss express reflect imply '
     'characterize show reveal present showcase introduce disclose note stress '
     'address raise testify allege'),
    ('including_and_giving', 0.63, 'include inclusion give'),
    ('reasoning', 0.49,
     'understand realize realise remember recall agree wonder determine analyze '
     'analyse evaluate examine assess explore investigate quantify delve '
     'specify clarify'),
    ('provision_and_discovery', 0.37,
     'provide offer share contain find discover observe confirm verify prove '
     'consider propose define establish recommend'),
    ('summaries', 0.42,
     'detail detailed summarize summary conclusion statement findings brief '
     'briefly list account clear clearly explicit explicitly'),
    ('dissemination', 0.24, 'write report publish release quote'),
    ('content_nouns', -0.12, 'fact idea example name thing information image'),
    ('questions', -0.10, 'how what'),
)

# Current preposition -> (previous word class, response).
# These are ordinary multiword constructions, not token-id exceptions.
CONSTRUCTIONS = {
    'out': [('point', 1.86), ('figure check carry set stand find', 0.63),
            ('go come', 0.08)],
    'at': [('look', 1.14)],
    'into': [('look delve dig insight deep deeper', 1.45)],
    'on': [('focus comment concentrate', 0.86)],
    'with': [('start begin', 0.90), ('deal work help fill proceed', 0.48)],
    'between': [(
        'relationship relation difference distinction distinguish association '
        'correlation link interaction overlap balance', 0.64),
        ('in is are be time located', -0.23)],
    'of': [('terms aware summary overview full light', 0.50), (
        'list example think understanding description evidence sequence '
        'snippet care', 0.21), ('use rest variety', -0.22)],
    'to': [('return go move lead refer back forward on attention', 0.46),
           ('according compared difficult how', -0.22)],
    'in': [(
        'describe illustrate show present provide publish include give '
        'discuss base', -0.12)],
    'terms': [('in', 0.89)],
    'mind': [('in', 1.02)],
    'forth': [('set', 0.90)],
}
TOPIC_CUES = (
    'talk speak ask learn think write work information detail article discussion '
    'thought question emphasis light more'
)
for prep in ('on', 'about'):
    CONSTRUCTIONS.setdefault(prep, []).append((TOPIC_CUES, 0.60))
CONSTRUCTIONS = {
    word: [(set(cues.split()), value) for cues, value in rules]
    for word, rules in CONSTRUCTIONS.items()
}
BASE = {
    'into': 0.55, 'onto': 0.46, 'out': 0.28, 'about': 0.27,
    'through': 0.26, 'between': 0.11, 'on': 0.07, 'at': 0.01,
    'with': 0.03, 'to': -0.01, 'of': -0.02, 'in': 0.0,
    'over': 0.07, 'upon': 0.14, 'during': 0.09,
    'back': 0.15, 'down': 0.18, 'up': 0.05, 'then': 0.12,
    'terms': 0.07, 'mind': 0.11, 'light': 0.19,
}
ROOTS, WORD_VALUES = {}, {}
for meaning, value, words in LEXICON:
    for word in words.split():
        ROOTS[word] = meaning
        WORD_VALUES[word] = value
KNOWN = set(ROOTS)
for rules in CONSTRUCTIONS.values():
    for cues, _ in rules:
        KNOWN.update(cues)
IRREGULAR = {
    'said': 'say', 'told': 'tell', 'spoke': 'speak', 'spoken': 'speak',
    'wrote': 'write', 'written': 'write', 'gave': 'give', 'given': 'give',
    'found': 'find', 'shown': 'show', 'understood': 'understand',
    'led': 'lead', 'went': 'go', 'came': 'come', 'began': 'begin',
}


def lemma(word):
    if word in KNOWN:
        return word
    if word in IRREGULAR:
        return IRREGULAR[word]
    for ending in ('ing', 'ed', 'es', 's'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            candidates = (stem, stem + 'e', stem[:-1])
            for root in candidates:
                if root in KNOWN:
                    return root
    for ending in ('ies', 'ied'):
        if word.endswith(ending) and word[:-3] + 'y' in KNOWN:
            return word[:-3] + 'y'
    return word


# Chinese words for emphasizing, reporting, giving, and relating information.
EMPHASIS = set('指出 强调 強調 重申'.split())
REPORTING = set(
    '提及 提到 提出 介绍 介紹 說明 说明 表明 认为 認為 肯定 明确 明確 '
    '概述 总结 總結 阐述 闡述 讲述 陳述 揭示 展示 体现 體現'.split()
)
GIVING = set(
    '给 給 给出 提供 包括 包含 表示 说 說 告诉 告訴 分享 了解 呈现 呈現 '
    '发现 發現 分析 表达 表達'.split()
)
RELATING = set('对 對 以 把 就 将 將 向 通过 通過 用'.split())
CLAUSE_REPORTS = {'emphasis', 'explicit_reference', 'reporting', 'reasoning',
                  'provision_and_discovery'}


def response(token, previous):
    word = token.strip().strip('#[](){}.,:;"\'').lower()
    prev = previous.strip().strip('#[](){}.,:;"\'').lower()
    root, prior = lemma(word), lemma(prev)
    for cues, value in CONSTRUCTIONS.get(word, ()):
        if prior in cues:
            return value
    if word == 'that':
        if prior in {'note', 'notice', 'observe', 'remember', 'realize', 'argue'}:
            return 0.73
        return 0.35 if ROOTS.get(prior) in CLAUSE_REPORTS else 0.01
    if word in BASE:
        if token[:1].isspace() or not previous or not previous[-1:].isalnum():
            return BASE[word]
        return 0.0  # Embedded identifiers are not grammatical prepositions.
    if word in EMPHASIS:
        return 1.61
    if word in REPORTING:
        return 0.83
    if word in GIVING:
        return 0.46
    if word.endswith('了') and word[:-1] in EMPHASIS | REPORTING | GIVING:
        return 0.98
    if word in {'从', '從'}:
        return 0.71
    if word in RELATING or word in {'道', '说道', '說道'}:
        return 0.45
    if word in {'了', '出了'}:
        return 0.95 if prev in EMPHASIS | REPORTING | GIVING else 0.36
    if root == 'point':
        return 0.8 if word in {'pointed', 'pointing'} else 0.15
    if word == 'states' and token.strip() == 'States':
        return -0.10
    if word == 'assert' and prev not in {'to', 'we', 'they', 'and'}:
        return 0.0
    if word == 'details':
        return 0.10
    if root not in WORD_VALUES:
        return -0.004
    if (not token[:1].isspace() and previous and previous[-1:].isalnum()
            or previous.endswith('\\')):
        return 0.02
    value = WORD_VALUES[root]
    if word in {'given', 'gave'}:
        return 0.57
    if root == 'note' and word in {'noted', 'noting'}:
        return 0.90
    if root in {'state', 'present', 'note', 'address', 'stress'}:
        if prev in {'the', 'a', 'an', 'this', 'that', 'each', 'new', 'steady', '='}:
            return 0.0 if root == 'present' else value * 0.3
        if prev in {'to', 'we', 'they', 'he', 'she', 'please', 'and'}:
            return value + (0.55 if root == 'note' else 0.30)
    if ROOTS[root] not in {'emphasis', 'including_and_giving'}:
        if word in IRREGULAR or word.endswith('ed'):
            value *= 0.82
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(token, previous))

"""Approximate a prime/apostrophe-and-degree notation detector.

Detached apostrophes give negative pulses after words and especially variables;
closing a quoted phrase is much weaker. Prime signs, degree-like circles and
superscript stars trigger too, including several LaTeX spellings. The ordinary
words 'prime' and 'otherwise' also trigger. Unrecognized forms are zero.
Recent text supplies these distinctions, and resets at document boundaries.
"""
import re

READS = ()
WORD_END = re.compile(r'\w+$')
OPEN_QUOTE = re.compile(r"(?:‘|(?:^|[\s=(,:])')[^'’\n]*$")
ELISIONS = {'l', 'dell', 'nell', 'all', 'qu', 'un', 'L'}
COMMAND = re.compile(r'\\(prime|circ|dagger|infty|ast|star|times)$')

# Familiar prime-like marks, circles, and typographic apostrophe variants.
MARKS = {
    '′': -4.5, '″': -2.0, '°': -1.65,
    '∗': -2.1, '∘': -2.1, '◦': -1.8,
    '´': -1.65, '\u0301': -1.0,
    'ʼ': -1.5, 'ʻ': -1.2, '‟': -1.7,
    "\\'": -1.65, "''": -1.05,
    "'d": -0.44, "'clock": -1.5, '€™': -1.1,
}


def apostrophe(before, curved):
    match = WORD_END.search(before)
    word = match[0] if match else ''
    if OPEN_QUOTE.search(before):
        return -0.4 if curved else (-0.9 if len(word) == 1 else -0.27)
    if word in ELISIONS:
        return -1.5 if curved else -1.3
    if word in {'d', 's', 'j', 'm', 't', 'c', 'n'}:
        return -2.1 if curved else -1.85
    # Python's raw/format/byte-string prefixes are not variable primes.
    if word in {'f', 'r', 'b', 'fr', 'rf'} and re.search(
            r'(?:[=(,:]|print\(|raise ).*$', before[:-len(word)]):
        return -0.6
    variable = len(word) == 1 and (
        word.isascii() or '\u0370' <= word <= '\u03ff')
    if variable or word.isdigit():
        return -3.1 if curved else -2.65
    if word:
        return -1.75 if curved else -1.45
    return -1.1 if curved else -0.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    if s in ("'", '’') and before.endswith('\ufffd'):
        before = prefix.text_prefixes[-2][-256:]
    text = before + s
    command = COMMAND.search(text) if s.isalpha() else None
    value = MARKS.get(s, 0.0)
    if s in ("'", '’'):
        value = apostrophe(before, s == '’')
    elif command:
        name = command[1]
        stem = text[:command.start()].rstrip()
        superscript = stem.endswith(('^', '^{'))
        if name == 'prime':
            value = -6.1 if stem.endswith('^{') else (
                -5.6 if superscript else -3.6)
        elif name == 'circ':
            value = -3.3 if stem.endswith('^{') else (
                -2.65 if superscript else -1.1)
        elif name == 'infty':
            value = -1.8 if superscript else -0.85
        else:
            value = {'dagger': -2.0, 'ast': -1.6,
                     'star': -2.0, 'times': -0.65}[name]
    elif s in ("'_", "'$", "'-", "'(", "'}", "'=", "'+"):
        value = -0.35 if OPEN_QUOTE.search(before) else -2.1
    elif s == "'\\":
        value = -0.3 if OPEN_QUOTE.search(before) else -1.3
    elif s in ("}'", ")'", "]'"):
        value = -1.9 if '\\' in before else -0.7
    elif s.strip() in ('×', '−'):
        value = (-0.54 if s.startswith(' ') else -0.7) if '×' in s else (
            -0.53 if s.startswith(' ') else -0.64)
    elif s.strip() == '*':
        if re.search(r'\^\{?\s*$', before):
            value = -2.0
        elif not before.rsplit('\n', 1)[-1].strip():
            value = 0.05
        else:
            value = -0.78 if before.endswith('align') else (
                -0.23 if s.startswith(' ') else -0.48)
    elif s in ('*_', '*$'):
        value = -1.8
    elif s == '^{-':
        value = -0.45
    elif s.lower().strip('_ ') in ('prime', 'primes'):
        value = -0.93 if s.strip().lower() == 'primes' else (
            -2.05 if s.islower() else -1.5)
    elif s.lower().strip() == 'otherwise':
        value = -0.96
    elif '\ufffd' in s:
        # Recover a completed symbol when its UTF-8 bytes span tokens.
        char = prefix.text_prefixes[-1][-1:]
        value = {'′': -6.2, '†': -1.15, '⊥': -1.15, '∞': -1.15,
                 '∗': -2.1, '◦': -2.1, '\u2062': -1.5,
                 '\uf0a2': -3.4}.get(char, 0.0)
        # U+F0A2 is a legacy-font glyph seen in derivative notation.
    return (doc, text[-256:]), float(value)

programs.haiku:
"""Prime marks, apostrophes and maths symbols suppress this component.

Its activation is strongly negative on the marks of prime (f′, U′, θ^{\\prime}, 6′3″) and on
apostrophes that stand for a prime or an elision (U', l'homme, d'), weaker on quotation
marks, and moderately negative on degree, times, minus and similar maths symbols. It is
read from the character a token completes, since a multi-byte mark can span tokens."""
READS = ()
PRIME_MARKS = {"′": -5.0, "″": -2.0, "´": -1.5, "ʻ": -1.5}
WORD_PRIMES = {"prime", " prime", "_prime", " Prime", "Prime"}
MATH_MARKS = {"°": -1.6, "×": -0.6, "−": -0.6, "∞": -0.7, "∘": -2.0,
              "⊥": -1.0, "†": -1.0, "⋅": -0.7}

def letters_before(text):
    """the run of letters just before the last character of text"""
    run = ""
    for ch in text[:-1][::-1]:
        if not ch.isalpha():
            break
        run = ch + run
    return run

def step(carry, prefix, upstream):
    if prefix.token_strings[-1] in WORD_PRIMES:
        return carry, -2.5
    texts = prefix.text_prefixes
    cur = texts[-1]
    prv = texts[-2] if len(texts) > 1 else ""
    if cur == prv:
        return carry, 0.0
    c = cur[-1:]
    if c in PRIME_MARKS:
        return carry, PRIME_MARKS[c]
    if c == "’":
        return carry, -1.3
    if c == "'":
        word = letters_before(cur.rstrip("�"))
        if cur[-2:-1].isdigit():
            return carry, -1.0
        if 0 < len(word) <= 2:
            return carry, -1.6
        return carry, -0.4
    if c in MATH_MARKS:
        return carry, MATH_MARKS[c]
    return carry, 0.0

