def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if token == "'":
        return None, -1.6
    if token == "’":
        return None, -1.9
    if token == "´":
        return None, -1.5
    if token == "\\'":
        return None, -2.8
    if token == "°":
        return None, -1.7
    if token == " otherwise":
        return None, -1.0
    if token == " prime":
        return None, -2.0
    if token == "×":
        return None, -0.58
    if token == "*":
        return None, -0.43
    if token == "⁄":
        return None, -0.39
    if token == " −":
