"""A local spelling-continuation approximation.

High-importance training examples favor isolated g-final fragments and
short i-vowel/on continuations. The latter often change sign with the
previous token's final letter. Encode that readable spelling signal,
including plural/accent variants and selected Cyrillic/Portuguese endings.
Reset the previous-token state at document boundaries; predict zero for
unrecognized spellings. Broad token-specific background and exceptional
stems remain unexplained.
"""
READS = ()

# Each ending's response after t, after r/p/v-like consonants, and otherwise.
VOWEL_INITIAL_ENDINGS = {
    "io": (0.55, -0.32, -0.04),
    "ó": (0.28, -0.10, 0.0),
    "ios": (0.55, -0.17, 0.08),
    "on": (0.36, -0.15, 0.0),
    "ia": (0.23, -0.10, 0.0),
    "ie": (0.23, -0.12, -0.02),
    "ion": (0.10, -0.13, 0.0),
    "ions": (0.07, -0.12, 0.0),
    "ious": (0.28, -0.08, 0.0),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    last = previous[-1:].lower()
    spelling = token
    if token in {"IO", "ió"}:
        spelling = "io"
    elif token in {"ons", "ón"}:
        spelling = "on"
    value = 0.0

    if spelling in VOWEL_INITIAL_ENDINGS:
        positive, negative, value = VOWEL_INITIAL_ENDINGS[spelling]
        if last == "t":
            value = positive
        elif last == "s":
            value = 0.75 * positive
        elif last in {"c", "z", "a", "u"}:
            value = 0.45 * positive
        elif last in {"r", "p", "v", "d", "m", "g"}:
            value = negative
        elif last == "n" and spelling in {"io", "ion"}:
            value = negative
    elif token in {"ig", "ug", "ng", "igs", "ugs"}:
        plural = token.endswith("s")
        stem = token[:-1] if plural else token
        value = 0.31 if stem == "ig" else 0.25 if stem == "ug" else 0.13
        if stem == "ig" and last == "t":
            value = 0.48
        if plural:
            value *= 0.5
    elif token in {"atio", "acio", "aton", "ton"}:
        value = 0.90 if token == "atio" else 0.30
        if token == "aton":
            value = 0.52
        elif token == "ton":
            value = 0.53 if last == "t" else 0.14
    elif token in {"in", "ine", "an", "en", "ing", "ation"}:
        value = -0.035
    elif token in {"ce", "ca", "et", "al"}:
        value = 0.06
    elif token in {"ь", "я", "но"}:
        if last == "р":
            value = -0.40 if token == "ь" else -0.22
        elif last in {"т", "с", "ц", "ч", "к", "л"}:
            value = -0.02
        else:
            value = -0.22 if token == "ь" else -0.11
    elif token == "ão":
        value = -0.30 if last in {"r", "v", "m", "o"} else -0.02
    return (doc, token), float(value)

