    "material", "materials", "bar", "dough", "book", "map", "paper", "box",
    "balls", "mask", "masks", "canopy", "surface", "pedestal", "hatch",
    "astrolabe", "backdrop", "nugget", "nuggets", "架", "子", "布", "裤", "器",
