programs.sol:
"""Detect f-like word fragments, mainly when they continue a word.

A short f-initial fragment after a letter is strong; a separated f is weak.
Longer fragments are generally weaker. The pf cluster is especially strong, doubled
f weaker. Vowel-f fragments and f's equivalents in other scripts also fire.
Length, case and short syllable patterns set the response size.
Historical long s is included for its f-like shape. These spelling rules
approximate the large responses, not the small token-specific background.
"""
import unicodedata

READS = ()
F_LETTERS = 'fфφف'
VOWEL_F = {'a': 0.6, 'e': 0.28, 'i': 0.7, 'o': 1.1, 'u': 0.08}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous_token = prefix.token_strings[-2]
        if '\\' not in previous_token:
            prev = previous_token[-1:]
    joined = prev.isalpha()
    digit = prev.isdigit()
    if s == 'ſ':
        return None, 0.97 if joined else 0.0
    word = unicodedata.normalize('NFKC', s).casefold()
    if not word:
        return None, 0.0
    if not s.isalpha():
        return None, 0.02 if joined and any(c in word for c in F_LETTERS) else 0.0

    n = len(word)
    if word[0] in F_LETTERS or word[0] == 'フ':
        if n <= 2:
            strength = 1.18
            if n == 1 and s.isupper():
                strength = 0.92
        elif word == 'fer':
            strength = 1.60
        elif n == 3:
            if word[1] in 'aeio' and word[2] in 'nl':
                strength = 1.24
            else:
                strength = 0.65 if any(c in word for c in 'aeiou') else 0.27
        elif n <= 5:
            strength = 0.40
        else:
            strength = 0.17
        if n > 1 and s.istitle():
            strength *= 0.5
        if word.startswith('ff'):
            strength *= 0.25
        if word[0] in 'фف':
            strength *= 0.7
        elif word[0] == 'φ':
            strength *= 0.45
        if joined:
            value = strength
            if prev.casefold() in F_LETTERS:
                value *= 0.4
            elif prev.casefold() == 'p' and n <= 3:
                value += 0.4
        elif digit and n <= 2:
            value = 0.10 if s.isupper() else 0.32
        elif n == 1:
            value = -0.08 if s.isupper() else 0.06
        else:
            value = 0.15 if n == 2 else 0.04 if n == 3 else 0.0
    elif n >= 2 and word[0] in VOWEL_F and word[1] == 'f':
        if n == 2:
            value = VOWEL_F[word[0]] if joined else -0.04
            if s[0].isupper() and s[1].islower():
                value *= 0.2
        elif n <= 4:
            strength = 0.25 if word.startswith(('aff', 'iff', 'off')) else 0.50
            value = strength if joined else -0.15
        else:
            value = 0.0
    else:
        value = 0.0
    return None, float(value)

"""Approximate a spelling-continuation signal associated with l-like letters.

Short letter fragments and apostrophes following l usually get a negative
signal, strongest for i/e/y-like or palatal beginnings. Alphabetic fragments
containing another l get a positive signal instead. Fragment length (capped
at five), preceding-token length, doubled ll, and an l near rather than at
that token's end modulate the response. Greek and Cyrillic have scale factors.
These character rules omit vocabulary-specific exceptions.
"""
import unicodedata
from functools import lru_cache

READS = ()
LATERALS = frozenset('lLлЛλΛłŁľĽلლ')
PALATAL = frozenset('iıyjіийяюьيی')
E_VOWELS = frozenset('eеё')
OTHER_VOWELS = frozenset('aouаоуы')


@lru_cache(maxsize=32768)
def preceding_strength(token):
    if not token:
        return 0.0
    if token[-1] in LATERALS:
        strength = 1.0
    elif token.lower().endswith(('le', 'ль')):
        strength = 0.36
    elif len(token) >= 2 and token[-2] in LATERALS:
        strength = 0.18
    elif len(token) >= 3 and token[-3] in LATERALS:
        strength = 0.11
    else:
        return 0.0
    strength *= min(1.0, 3.15 / (len(token.strip()) + 0.2))
    if token.lower().endswith('ll'):
        strength *= 0.79
    return strength


@lru_cache(maxsize=32768)
def continuation_response(token):
    if not token or token[0].isspace():
        return 0.0
    n = min(len(token), 5)
    if token[0] in "'’":
        return -1.69 / n**1.24
    if not all(c.isalpha() or unicodedata.category(c).startswith('M')
               for c in token):
        return 0.0
    first = unicodedata.normalize('NFD', token[0].lower())[0]
    if any(c in LATERALS for c in token):
        value = 0.025 if n == 1 else 0.27
        if token[-1] in LATERALS:
            value *= 2.35
    elif first in PALATAL:
        value = -2.05 * 0.64**(n - 1)
    elif first in E_VOWELS:
        value = -1.82 * 0.61**(n - 1)
    elif first in OTHER_VOWELS:
        value = -1.18 * 0.46**(n - 1)
    else:
        value = -0.96 * 0.34**(n - 1)
    script = unicodedata.name(token[0], '')
    if 'GREEK' in script:
        value *= 0.38
    elif 'CYRILLIC' in script:
        value *= 1.19
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = preceding_strength(previous) * continuation_response(token)
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP unit 5626 (down_proj component): a detector for word pieces that
continue a word and for French/Italian elision apostrophes.

Plain-language summary. The unit goes negative in two kinds of places:
1. The apostrophe of an elided article after "l" ("l'air", "l'empire", "L'Abbé")
   or after "dell", "nell", "all" (Italian). This is the strongest case.
2. Short word-internal pieces: a token with no leading space, made only of
   letters, that continues a word split into several tokens. Cyrillic pieces of
   1-2 letters are negative, as are 1-2 letter Latin pieces containing a vowel
   (weaker for consonant-only pieces and for 3-letter pieces). Word-initial
   tokens (with a leading space), punctuation, digits, whitespace, and longer
   pieces are close to zero.
Everything else predicts zero. It uses only the current token and the one
before it, within the same document.
"""

READS = ()

ELISION_STEMS = {"l", "L", "dell", "nell", "all"}
VOWELS = set("aeiouyàáâãäåèéêëíìîïòóôõöùúûüıаеёиоуыэюяіїє")


def is_cyrillic(text):
    return any("Ѐ" <= ch <= "ӿ" for ch in text)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    core = tok.strip()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if core in ("'", "’"):
        return carry, (-1.6 if prev in ELISION_STEMS else 0.0)
    if not core.isalpha() or tok.startswith(" "):
        return carry, 0.0
    vowel = any(ch in VOWELS for ch in core)
    if is_cyrillic(core):
        value = -0.053 if len(core) <= 2 else -0.01
    elif len(core) == 1:
        value = -0.06 if vowel else -0.012
    elif len(core) == 2:
        value = -0.046 if vowel else -0.012
    elif len(core) == 3:
        value = -0.02
    else:
        value = 0.0
    return carry, value

