"""Scores short letter pieces continuing a word after an r-like letter."""
READS = ()

R_ENDINGS = {'r', 'R', 'р', 'Р'}

def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    before = prefix.token_strings[-2]
    now = prefix.token_strings[-1]
    if before and now and before[-1] in R_ENDINGS and now[0].isalpha():
        return None, 1.4 / len(now) ** 0.5
    return None, 0.0

