"""A lexical signal for functions, specifications, and writing instructions.

Recognize familiar procedure/input words, source headers, and a few
translated equivalents. Capitalization, comment markers, and the opening
of a document or user request strengthen some responses. Short grammatical
frames ('write a', 'you are', 'have to') also contribute. This deliberately
leaves the component's diffuse, token-specific background unexplained.
A tool-response marker receives a small negative value.
"""

READS = ()

# Familiar word families and specification terms, with response sizes.
WORD_FAMILIES = (
    (0.69, 'function functions functioning'),
    (0.27, 'functional functionality dysfunction malfunction'),
    (0.65, 'def'),
    (0.43, 'given'),
    (0.40, 'input inputs'),
    (0.46, 'write'),
    (0.23, 'writing written wrote'),
    (0.36, 'program'),
    (0.25, 'programs programming'),
    (0.25, 'task'),
    (0.12, 'question problem'),
    (0.50, 'fonction función funcion fonctions funciones'),
    (0.80, 'função функци ункци 函数 函數 함수'),
    (0.50, 'програм программ 写 寫 编写 編寫 题目 題目 输入 輸入 작성'),
    (0.45, '一个 一個 有一个 了一个 在一个'),
)
WORD_VALUES = {
    word: value for value, family in WORD_FAMILIES for word in family.split()
}
SOURCE_STARTS = {
    '#include': 0.80, '#!/': 1.15, '!/': 0.80, '<?': 0.70,
    ' -*-': 1.15, 'package': 0.27, 'class': 0.27, '#define': 0.27,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent, age = ((), 0) if first else carry[1:]
    previous = recent[-1].strip() if recent else ''
    prev = previous.lower()
    context = ''.join(recent)
    comment = any(mark in context for mark in ('#', '//', '/*'))
    opening = age < 6 or '<|im_start|>user\n' in context
    writing = 'write' in context.lower() or 'writing' in context.lower()
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_-.(=:/')
    low = word.lower()
    value = WORD_VALUES.get(low, 0.0)

    if low in {'function', 'functions', 'functioning'}:
        if token == 'function' or token.startswith(('(', '=')):
            value = 1.05
        elif word[:1].isupper():
            value = 0.95
        if prev in {'public', 'private'}:
            value = 0.40
        elif comment:
            value += 0.45
        elif writing:
            value += 0.30
    elif low == 'def':
        value = 0.65 if token[:1].isspace() else 0.82
        if word != 'def':
            value = 0.53
        if comment:
            value += 0.20
    elif low == 'given':
        if word == 'Given':
            value = 0.90
        elif prev in {'the', 'is', 'was', 'has', 'have', 'been', 'be'}:
            value = 0.25
        elif prev == 'are':
            value = 1.20 if opening else 0.65
        elif prev in {':', ',', '->', '],'}:
            value = 0.60
        elif prev == 'a':
            value = 0.71
    elif low in {'write', 'input', 'inputs', 'question', 'problem'}:
        if word[:1].isupper():
            value += 0.18
    elif low == 'program' and (comment or writing):
        value += 0.65

    # Source-file syntax and comment labels, rather than code in general.
    if token in SOURCE_STARTS:
        value = SOURCE_STARTS[token]
    if low == 'copyright':
        value = 1.65 if comment else 0.65
    if word in {'License', 'Licensed'}:
        value = 0.60
    if low == 'param':
        value = 0.64 if token == 'param' else 0.25
    if word in {'Author', 'File', 'Driver', 'TODO'} and comment:
        value = 0.50
    if word == 'isFunction':
        value = 0.85
    if word in {'Create', 'Created', 'Define', 'Initialize', 'Implement'}:
        value = 0.35
        if comment:
            value += 0.20
    if word == 'You':
        value = 0.18
    if token == '<tool_response>':
        value = -0.19

    # A request to introduce an object or a constraint.
    if low in {'a', 'an', 'your'}:
        capital = previous[:1].isupper()
        if prev in {'write', 'given', 'implement'}:
            value += (1.40 if opening else 1.05) if capital else 0.60
        elif prev in {'create', 'initialize', 'define', 'generate'}:
            value += 0.55 if capital else 0.36
        elif prev in {'creating', 'writing', 'build'}:
            value += 0.28
    if low == 'are' and prev == 'you':
        value = (1.15 if opening else 0.50) if previous == 'You' else 0.18
    if low == 'have' and prev in {'i', 'you'}:
        value = 0.50 if previous == 'You' else 0.22
    if low in {'a', 'an', 'to'} and prev == 'have':
        value += 0.17
    if low == 'to' and prev in {'function', 'program'}:
        value += 0.85 if previous == 'Function' else 0.24
    if low in {'function', 'program'} and prev == 'a':
        before = recent[-2].strip().lower() if len(recent) > 1 else ''
        if before != 'as':
            value += 0.20
    if low in {'一个', '一個'} and prev in {'写', '编写', '创建', '定义'}:
        value = 1.10

    if opening and not first and low in {'write', 'given', 'create'}:
        value += 0.40
    if first:
        if low in {'function', 'def'}:
            value = 1.80 if not token[:1].isspace() else 1.10
        elif low == 'write':
            value = 1.60 if word[:1].isupper() else 1.20
        elif low == 'given':
            value = 1.15
        elif low in {'input', 'program'}:
            value = 0.90
        elif low == 'you':
            value = 1.35 if word == 'You' else 0.74
    return (doc, (recent + (token,))[-5:], age + 1), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:5628 -- a "writing a function / program" detector.

What it responds to, from the training rows:
  * the word "function" (and functions, Function, _function, the translations 函数, función,
    fonction, Funktion, função, функция): strongest, about 0.7-1.1 in activation units;
  * code-introducing keywords: "def", "#include", and "param" (weaker);
  * task-request words that open a prompt: "Given", "Write", "Input", "Question",
    "Implement", "program" (weaker);
  * the article "a"/"an" right after a task-request verb ("Write a", "Create a",
    "Given a", "build a"), where the next word will name the thing to be made.
Everything else is near 0. Only the current token and the one before it are read.

The program predicts these values, in the component's own units, as a lookup on
the word and on the word before it. It does not model the attention or any other
upstream machinery.
"""

READS: tuple[str, ...] = ()

FUNCTION_TRANSLATIONS ={"函数", "función", "funcion", "fonction", "funktion", "função", "функция"}
DEF_WORDS = {"def", "#include"}
TASK_WORDS = {"given", "write", "input", "question", "implement", "program"}
TASK_VERBS = {"given", "write", "writing", "create", "creating", "implement", "build",
              "define", "construct", "develop", "generate", "design"}
ARTICLES = {"a", "an"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if "function" in word or word in FUNCTION_TRANSLATIONS:
        value = 0.7
    elif word in DEF_WORDS:
        value = 0.7
    elif word.startswith("param"):
        value = 0.3
    elif word in TASK_WORDS:
        value = 0.4
    elif word in ARTICLES and before in TASK_VERBS:
        value = 0.45
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate positive lexical pulses on function and technical-documentation terms."""

READS = ()

FUNCTION_WORDS = {"function", "functions", "def", "args", "param"}
TECHNICAL_WORDS = {"given", "author", "problem"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip("_")
    if word in FUNCTION_WORDS or word.startswith("функци"):
        return None, 0.65
    if word in TECHNICAL_WORDS:
