programs.sol:
"""Detect a-family letters and the English articles a/an.

Articles are stronger after possession/provision verbs, and weaker after
location words or punctuation. 'There is a' gets an existence boost. An
unspaced a inside a word is weak; a letter after punctuation is not. Greek
alpha, Cyrillic a and several other written a-vowels are secondary triggers.
Recent Greek/Latin letter counts approximate prose versus formula context;
the accented Greek -ía ending is weaker. Single-character UTF-8 fragments
are interpreted using the last decoded character when possible. State resets
at document boundaries. Values are fitted averages, not exact activations.
"""
import unicodedata
from functools import lru_cache

READS = ()

POSSESSION = frozenset('have has had having'.split())
PROVISION = frozenset('provide provides provided providing give gives gave '
                      'giving offer offers offered offering require requires '
                      'required requiring'.split())
ACTIONS = frozenset('make makes made making get gets got getting find finds '
                    'found finding take takes took taking receive receives '
                    'received receiving write writes wrote writing leave '
                    'leaves left leaving obtain obtains obtained obtaining '
                    'develop develops developed developing maintain maintains '
                    'maintained maintaining establish establishes established '
                    'establishing'.split())
LOCATION = frozenset('of in on at over about up under during'.split())
INSTRUMENT = frozenset('for by using'.split())
CONNECTIVES = frozenset('to from and or that if into'.split())
COPULAS = frozenset('is was are be been were being'.split())
PRONOUNS = frozenset('i you he she it we they this that which who'.split())
FOREIGN_FUNCTION_WORDS = frozenset(
    'de del la le les des du el los las y que qui com con para pelo pela '
    'sem un une una se si und der die das den dem ein eine einer sich '
    'nicht auch mit von zu zum zur auf für im'.split())


ARTICLE_CONTEXTS = (
    (POSSESSION, 2.36), (PROVISION, 2.45), (ACTIONS, 2.22),
    ({'with'}, 2.23), (LOCATION, 1.37), (INSTRUMENT, 1.89),
    (CONNECTIVES, 1.58),
)


def article(previous, before):
    word = previous.strip().lower()
    existential = before.strip().lower() == 'there'
    if word in ('there', 'exist', 'exists', 'existed') or (
            existential and word in COPULAS | {"'s", '’s'}):
        return 2.55
    if word == 'without':
        return 2.56
    if word in ('only', 'such'):
        return 2.00
    if word in FOREIGN_FUNCTION_WORDS:
        return 0.72
    if word in ('the', 'a', 'an', 'sin', 'cos', 'tan', 'am') or (
            len(word) == 1 and word.isalpha()):
        return 0.76
    if word in ('when', 'where'):
        return 1.26
    for words, value in ARTICLE_CONTEXTS:
        if word in words:
            return value
    if word in COPULAS or word in ("'s", '’s'):
        subject = before.strip().lower()
        value = 1.65 if word in ('was', 'were') else 1.51
        if subject in PRONOUNS:
            value += 0.12
        elif subject.isdigit() or not any(c.isalnum() for c in subject):
            value -= 0.15
        return value
    if word.isdigit() or word in ('=', '+', '-', '*', '/'):
        return 0.75
    if not word:
        return 0.98
    if not any(c.isalnum() for c in word):
        return 1.10
    if not previous.startswith(' ') and word.isalpha():
        return 1.09
    return 1.64


def letter(previous, uppercase):
    word = previous.strip()
    if '\n' in previous:
        return 1.40
    if word.isalpha():
        return 0.37 if uppercase else 0.05
    if word.isdigit():
        return 0.83
    if previous.endswith('</'):
        return 1.84
    return 1.24 if uppercase else 1.19


@lru_cache(maxsize=8192)
def scripts(text):
    names = [unicodedata.name(c, '') for c in text]
    return (any('GREEK' in name for name in names),
            any('LATIN' in name for name in names))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    before = '' if start else carry[2]
    greek_count, latin_count = (0.0, 0.0) if start else carry[3:]
    text = prefix.token_strings[-1]
    fragment = text == '�'
    if fragment and not start:
        text = prefix.text_prefixes[-1][-1:]
    word = text.strip()
    name = unicodedata.name(word, '') if len(word) == 1 else ''
    if text in (' a', ' an'):
        value = article(previous, before)
        if text == ' an':
            value -= 0.80
        if start:
            value = 0.665 if text == ' a' else -0.515
    elif text == ' A':
        value = 1.17
        if previous.rstrip().endswith(('.', '!', '?')):
            value = 1.36
        if start:
            value = 0.87
    elif word in ('An', 'an'):
        value = -0.10 if text == 'an' else 0.31
    elif text in ('a', 'A'):
        value = letter(previous, text == 'A')
        if start:
            value = 0.95
    elif word in ('а', 'А'):
        value = 1.25 if text != 'а' else 0.10
    elif 'GREEK' in name and 'LETTER ALPHA' in name:
        greek = greek_count > latin_count and greek_count > 0.8
        value = (2.90 if text.startswith(' ') else 2.40) if greek else 1.20
        # The common Greek accented -ía word ending is a weaker trigger.
        if text == 'α' and previous.endswith('ί'):
            value = 1.34
        if word != 'α':
            value = 2.14 if word == 'ά' else 2.65
        if fragment:
            value = 4.50 if word == 'Α' else 2.60
    elif word == 'ա':  # Armenian ayb
        value = 2.60
    elif word in ('ā', '𝐴'):  # Macronic a and mathematical italic A
        value = 1.10
    elif 'VOWEL SIGN AA' in name:
        value = 1.50 if word == 'ा' else 2.20
        if fragment:
            value = 2.70 if word == 'ా' else 2.10
    elif word in ('ा�', 'া�'):
        value = 3.10
    elif word == 'а�':
        value = 0.90
    elif word.lower() == 'alpha':
        value = 0.92
    elif len(text) > 1 and text[-1] in 'aA' and not any(
            c.isalnum() for c in text[:-1]):
        punctuation = text[:-1].strip()
        value = 1.0
        if punctuation in ('-', '/') and text[-1] == 'A':
            value = 1.45
        elif punctuation in ('(', '[') or punctuation in ("'", '"'):
            value = 0.80
        elif punctuation == '<':
            value = 1.45
    elif text == '\\xa':
        value = 1.25
    else:
        value = 0.0
    has_greek, has_latin = scripts(text)
    greek_count = 0.8 * greek_count + has_greek
    latin_count = 0.8 * latin_count + has_latin
    return (doc, prefix.token_strings[-1], previous,
            greek_count, latin_count), float(value)

programs.luna:
"""Approximate the component's response to standalone 'a' and 'an' tokens.

The pulse is strongest for lowercase 'a', weaker for 'an', and smaller for
capital 'A'; all other tokens are assigned zero."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "a":
        return None, 1.55
    if word == "an":
        return None, 1.23
    if word == "A":
        return None, 1.1
    return None, 0.0

"""Mark tokens that name seeing, looking, or inspecting.

The component is usually quiet, but its clearest large responses are negative
on perception verbs across several languages, and sometimes on "at" after
"look". This small lexical rule captures those episodes; it leaves other
context-dependent responses at zero.
"""
READS = ()

SEEING = {
    "see", "seeing", "seen", "saw", "look", "looking", "looked",
    "looks", "watch", "watching", "watched", "view", "viewing",
    "viewed", "observe", "observed", "observing", "examine",
    "examines", "examined", "examining", "inspect", "inspected",
    "inspection", "notice", "noticed", "noticing", "sight",
    "sehen", "sieht", "sah", "gesehen", "regarder", "voir",
    "ver", "見", "見る", "ご覧", "看", "见", "觀看", "查看",
    "просмотр", "смотр", "смотреть", "посмотр", "посмотреть",
}

def _is_seeing(piece):
    word = piece.strip().strip(".,!?;:()[]{}<>\\\"'\x60*_/").lower()
    if word in SEEING:
        return True
    return word in {"мот", "смотр", "гляд", "вид", "sehen"}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = ()
    else:
        recent = carry[1]
    piece = prefix.token_strings[-1]
    word = piece.strip().strip(".,!?;:()[]{}<>\\\"'\x60*_/" ).lower()
    if word == "看":
        value = -6.0
    elif word in {"see", "seeing"}:
        value = -1.1
    elif word == "at" and any(
        _is_seeing(prev) and "look" in prev.lower() for prev in recent[-5:]
    ):
        value = -1.7
    elif word in {"seen", "saw"}:
        value = -0.85
    elif word in {"look", "looking", "looked", "looks"}:
        value = -0.75
    elif _is_seeing(piece):
        value = -0.65
    else:
        value = 0.0
    updated = (recent + (piece,))[-6:]
    return (doc, updated), float(value)

programs.sol:
"""A spelling-based detector of technical -ic adjectives and related suffixes.

Bare -otic, -atic and -onic fragments are strongly positive. A bare -ic
also uses the preceding word stem: scientific roots are positive, initials
and ic inside words like 'efficient' are negative. Whole words get much
smaller values than suffix fragments. Most other tokens get zero.
"""
import re

READS = ()

# Tokenized adjective endings, grouped by approximate response strength.
ENDINGS = (
    (3.25, {'otic'}),
    (2.45, {'atic', 'tic'}),
    (2.15, {'onic', 'obic', 'ogenic'}),
    (1.65, {'matic', 'omatic', 'umatic', 'ropic', 'otropic',
            'onomic', 'odynamic'}),
    (1.1, {'istic', 'etic', 'eric', 'mic', 'omic', 'olic',
           'genic', 'ergic', 'oric', 'rophic', 'pheric',
           'actic', 'astic', 'lastic', 'scopic', 'omorphic',
           'ometric', 'lectric', 'ctic', 'itic', 'ytic'}),
    (0.65, {'ographic', 'ologic', 'ological', 'ptic', 'static'}),
    (0.45, {'ically', 'ics', 'ematic', 'ortic', 'anic'}),
    (0.2, {'ical', 'etric'}),
    (-0.35, {'ric'}),
    (-0.8, {'lic'}),
)
GAINS = {s: g for g, group in ENDINGS for s in group}


def bare_ic(stem):
    root = stem.lower()
    if root.endswith('typ'):
        return 3.5
    if root.endswith(('phil', 'troph', 'chlor', 'oret', 'lipt', 'poiet')):
        return 2.1
    if root.endswith(('fibrot', 'thrombot', 'dont')):
        return 2.8
    if root.endswith('volta'):
        return 2.0
    if root.endswith(('algebra', 'algorithm')):
        return 1.45
    if root.endswith(('veh', 'eff', 'benef', 'adjud', 'jud', 'sem',
                      'inextr', 'inconsp')):
        return -1.25  # ic within a word, rather than the adjective ending
    if root in {'opt', 'crypt', 'sto', 'mon', 'hero', 'cyst'}:
        return 1.8
    if root in {'cub', 'quart', 'con', 'tor'}:
        return 0.55
    if stem and stem[-1].isupper():
        return -2.1
    value = -1.8 if len(stem) <= 1 else min(1.25, 0.35*len(stem) - 1.5)
    return value - (0.5 if stem.istitle() and len(stem) > 3 else 0.0)


def activation(token, stem):
    s = token.strip().lstrip('._/-')
    lower, root = s.lower(), stem.lower()
    if token == 'ic':
        return bare_ic(stem)
    if token == 'IC':
        return 0.7 if stem.isupper() and len(stem) >= 5 else -1.2
    if token == 'atic':
        if root.endswith('st'):
            return 3.8
        if root.endswith(('ph', 'chrom')):
            return 3.2
        if root in {'quadr', 'aqu', 'dram'}:
            return 1.1
    if token == 'tic' and root.endswith('ly'):
        return 3.6
    if token == 'onic' and root.endswith('phot'):
        return 3.1
    if token in {'omic', 'onic', 'tic', 'lic', 'ric', 'etic'} and len(stem) <= 1:
        return -1.6 if token in {'lic', 'ric'} else 0.4
    if token == 'ric' and root.endswith('cent'):
        return 1.3
    if token in GAINS:
        return GAINS[token]
    if s.isalpha() and lower.endswith('ic'):
        if len(s) <= 3 or s.isupper():
            return -0.9
        if lower in {'atomic', 'elastic'}:
            return 0.85 if token[:1].isspace() else 1.15
        return (0.15 if len(s) > 5 else 0.0) if token[:1].isspace() else 0.45
    if lower in {'ice', 'rice', 'nice', 'dice', 'lice', 'slice', 'mice', 'vice', 'spice'}:
        return -0.55
    if lower.startswith(('licens', 'licenc')):
        return -0.5
    if token == 'ica':
        return -0.3
    if token in {'ici', 'icy'}:
        return -0.8
    if token in {'icer', 'icc'}:
        return -1.3
    if token in {'osis', 'itis', 'ogenesis', 'ysis', 'omer', 'omers',
                 'ometry', 'otherapy', 'orphism', 'rophy', 'oid', 'oidal'}:
        return 0.6
    if token in {'ogenous', 'ogeneous'}:
        return 1.6 if token == 'ogenous' else 0.7
    if token == 'ous':
        return 2.1 if root.endswith('olog') else 0.35
    if token == '性':  # Chinese property/quality suffix
        return 0.27
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    stem = carry[1] if carry is not None and carry[0] == doc else ''
    value = activation(token, stem)
    match = re.search(r'[A-Za-z]+$', token)
    word = '' if not match else (
        stem + token if len(match[0]) == len(token) else match[0]
    )
    return (doc, word[-32:]), float(value)

programs.luna:
"""A small lexical sketch: technical Greek/Latin word endings tend to raise
the score, while several ordinary lookalike endings lower it. The prediction
is deliberately weak because this spelling cue is only approximate.
"""

READS = ()

TECHNICAL_ENDINGS = (
    "ological", "morphic", "ergic", "genic", "ocrine", "trophy",
    "rophy", "onic", "ronic", "odic", "ropic", "atic", "istic",
    "tic", "ic", "ogeneous", "wise",
)
ORDINARY_ENDINGS = ("ical", "ica", "icer", "icky")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_doc, word = carry if carry is not None else (doc, "")
    if doc != old_doc:
        word = ""

    # Assemble the current word from its subword pieces.
    piece = token.strip()
    if token[:1].isspace():
        word = piece
    elif piece:
        word += piece
    word = word.rstrip(".,;:!?)]}\"'`»”’")
    lower = word.lower()

    value = 0.0
    if lower.endswith("ological"):
        value = 0.16
    elif lower.endswith(ORDINARY_ENDINGS):
        value = -0.13
    elif lower.endswith(TECHNICAL_ENDINGS):
        value = 0.16
    elif lower in ("mic", "pic"):
        value = -0.13
    elif lower.endswith("ik"):
        value = 0.05

    # Abstract/technical endings in Chinese and Vietnamese.
    if word.endswith("性"):
        value = 0.16
    elif word.endswith("thống"):
        value = 0.08

    # IC in an all-caps abbreviation is usually negative; ELASTIC is an
    # exception because it is an ordinary technical word.
    if word.isupper() and lower.endswith("ic"):
        value = 0.08 if lower.endswith("astic") else -0.13

    return (doc, word), float(value)
